		});
	});

	it("does not hang when notify.open backpressures — bounded by PI_LENS_LSP_NOTIFY_BUDGET_MS", async () => {
		const prev = process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS;
		process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS = "50";
		try {
			const { LSPService } = await import("../../../clients/lsp/index.js");
			const service = new LSPService();
			const client = {
				isAlive: () => true,
				shutdown: async () => {},
				getWorkspaceDiagnosticsSupport: () => ({
					advertised: false,
					mode: "push-only" as const,
					diagnosticProviderKind: "none",
				}),
				getOperationSupport: () => ({}),
				// notify.open never resolves = a server whose stdin backpressures
				// (wedged/CPU-bound). Unbounded, this parked the dispatch LSP runner
				// until its 30s dispatcher timeout. It must now bail at the budget.
				notify: {
					announceCreated: () => undefined,
					open: vi.fn(() => new Promise(() => {})),
				},
				waitForDiagnostics: vi.fn().mockResolvedValue(undefined),
				getDiagnostics: vi.fn(() => []),
			};
			createLSPClient.mockResolvedValue(client);
			getServersForFileWithConfig.mockReturnValue([makeServer("python")]);

			const started = Date.now();
			const result = await service.touchFile(FILE, "print('x')\n", {
				clientScope: "primary",
				diagnostics: "document",
				collectDiagnostics: true,
				maxClientWaitMs: 25,
				maxDiagnosticsWaitMs: 50,
				source: "dispatch-lsp-runner",
			});
			const elapsed = Date.now() - started;

			expect(client.notify.open).toHaveBeenCalled();
			expect(elapsed).toBeLessThan(2000); // returned, did not hang on the write
			expect(result?.diags).toEqual([]); // no fresh diagnostics, but no hang
		} finally {
			if (prev === undefined) delete process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS;
			else process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS = prev;
		}
	});

	it("PI_LENS_LSP_DIAGNOSTICS_MAX_WAIT_MS overrides the option chain", async () => {
		const previous = process.env.PI_LENS_LSP_DIAGNOSTICS_MAX_WAIT_MS;
		process.env.PI_LENS_LSP_DIAGNOSTICS_MAX_WAIT_MS = "1000";
		try {
			const { LSPService } = await import("../../../clients/lsp/index.js");
			const service = new LSPService();
			const client = {
				isAlive: () => true,
				shutdown: async () => {},
				getWorkspaceDiagnosticsSupport: () => ({
					advertised: false,
					mode: "push-only" as const,
					diagnosticProviderKind: "none",
				}),
				getOperationSupport: () => ({}),
				notify: {
					announceCreated: () => undefined,
					open: vi.fn().mockResolvedValue(undefined),
				},
				waitForDiagnostics: vi.fn().mockResolvedValue(undefined),
				getDiagnostics: vi.fn(() => []),
			};

			createLSPClient.mockResolvedValue(client);
			getServersForFileWithConfig.mockReturnValue([makeServer("python")]);

			// Even with a higher explicit option, env wins via readEnvDiagnosticsWaitMs
			// because the touchFile resolution checks the env before the explicit option.
			// Verify: the env override of 1000 ms is what reaches the client.
			await service.touchFile(FILE, "print('x')\n", {
				clientScope: "primary",
				diagnostics: "document",
				collectDiagnostics: true,
				maxClientWaitMs: 8000,
				source: "dispatch-lsp-runner",
			});

			expect(client.waitForDiagnostics).toHaveBeenCalledWith(FILE, 1000);
		} finally {
			if (previous === undefined) {
				delete process.env.PI_LENS_LSP_DIAGNOSTICS_MAX_WAIT_MS;
			} else {
				process.env.PI_LENS_LSP_DIAGNOSTICS_MAX_WAIT_MS = previous;
			}
		}
	});

	// #570: a touch whose diagnostics wait TIMES OUT must never present as a
	// confirmed clean result — the returned array must be flagged
	// `inconclusive`, and (critically) a previously-confirmed non-empty
	// `lastKnownDiagnostics` record must survive the timeout untouched rather
	// than being wiped by an unconfirmed empty result.
	describe("#570 timeout does not present as confirmed-clean", () => {
		it("a timed-out touch does NOT clear lastKnownDiagnostics when there was a prior confirmed non-empty result", async () => {
			const { LSPService } = await import("../../../clients/lsp/index.js");
			const service = new LSPService();
			const diagnostic = makeDiagnostic("real error");
			const attributedDiagnostic = { ...diagnostic, serverId: "python" };
			// First client call: confirms one real diagnostic (fast, no timeout).
			let diagnosticsToReturn = [diagnostic];
			const client = {
				isAlive: () => true,
				shutdown: async () => {},
				getWorkspaceDiagnosticsSupport: () => ({
					advertised: false,
					mode: "push-only" as const,
					diagnosticProviderKind: "none",
				}),
				getOperationSupport: () => ({}),
				notify: {
					announceCreated: () => undefined,
					open: vi.fn().mockResolvedValue(undefined),
				},
				waitForDiagnostics: vi.fn().mockResolvedValue(undefined),
				getDiagnostics: vi.fn(() => diagnosticsToReturn),
			};
			createLSPClient.mockResolvedValue(client);
			getServersForFileWithConfig.mockReturnValue([makeServer("python")]);

			const firstResult = await service.touchFile(FILE, "print('x')\n", {
				clientScope: "primary",
				diagnostics: "document",
				collectDiagnostics: true,
				maxClientWaitMs: 8000,
				maxDiagnosticsWaitMs: 8000,
				source: "dispatch-lsp-runner",
			});
			expect(firstResult?.diags).toEqual([attributedDiagnostic]);
			expect((firstResult as any).inconclusive).not.toBe(true);
			expect(service.getLastKnownDiagnostics(FILE)).toEqual([
				attributedDiagnostic,
			]);

			// Second touch: content changed (so notify isn't skipped) and the
			// diagnostics wait is forced to time out via maxDiagnosticsWaitMs: 0
			// (timeoutMs resolves to 0, so `waitedMs + 20 >= timeoutMs` is always
			// true even though the mock wait resolves instantly). The server's
			// diagnostics cache reads back empty (as if cleared by the fresh
			// notify.open and nothing arrived yet) — this must NOT be read as a
			// confirmed clean result.
			diagnosticsToReturn = [];
			const secondResult = await service.touchFile(FILE, "print('y')\n", {
				clientScope: "primary",
				diagnostics: "document",
				collectDiagnostics: true,
				maxClientWaitMs: 8000,
				maxDiagnosticsWaitMs: 0,
				source: "dispatch-lsp-runner",
			});

			expect((secondResult as any).inconclusive).toBe(true);
			// #1179 shape-5: on the REAL producer result, `inconclusive` is an
			// enumerable OWN wrapper field, so it survives a copy of the result — it
			// would be dropped here if it were still the pre-#1179 non-enumerable
			// array side-channel with a spread intervening (#1094).
			expect(
				Object.prototype.propertyIsEnumerable.call(
					secondResult,
					"inconclusive",
				),
			).toBe(true);
			expect({ ...secondResult }.inconclusive).toBe(true);
			// The prior confirmed non-empty record must survive untouched.
			expect(service.getLastKnownDiagnostics(FILE)).toEqual([
				attributedDiagnostic,
			]);
		});

		it("a confirmed (non-timeout) empty result still clears lastKnownDiagnostics as before", async () => {
			const { LSPService } = await import("../../../clients/lsp/index.js");
			const service = new LSPService();
			const diagnostic = makeDiagnostic("real error");
			const attributedDiagnostic = { ...diagnostic, serverId: "python" };
			let diagnosticsToReturn = [diagnostic];
			const client = {
				isAlive: () => true,
				shutdown: async () => {},
				getWorkspaceDiagnosticsSupport: () => ({
					advertised: false,
					mode: "push-only" as const,
					diagnosticProviderKind: "none",
				}),
				getOperationSupport: () => ({}),
				notify: {
					announceCreated: () => undefined,
					open: vi.fn().mockResolvedValue(undefined),
				},
				waitForDiagnostics: vi.fn().mockResolvedValue(undefined),
				getDiagnostics: vi.fn(() => diagnosticsToReturn),
			};
			createLSPClient.mockResolvedValue(client);
			getServersForFileWithConfig.mockReturnValue([makeServer("python")]);

			await service.touchFile(FILE, "print('x')\n", {
				clientScope: "primary",
				diagnostics: "document",
				collectDiagnostics: true,
				maxClientWaitMs: 8000,
				maxDiagnosticsWaitMs: 8000,
				source: "dispatch-lsp-runner",
			});
			expect(service.getLastKnownDiagnostics(FILE)).toEqual([
				attributedDiagnostic,
			]);

			// Second touch: content changed, generous budget (no timeout), and the
			// server genuinely reports zero diagnostics this time — the existing
			// behavior (clear the cache, report clean) must be unchanged.
			diagnosticsToReturn = [];
			const secondResult = await service.touchFile(FILE, "print('y')\n", {
				clientScope: "primary",
				diagnostics: "document",
				collectDiagnostics: true,
				maxClientWaitMs: 8000,
				maxDiagnosticsWaitMs: 8000,
				source: "dispatch-lsp-runner",
			});

			expect(secondResult?.diags).toEqual([]);
			expect((secondResult as any).inconclusive).not.toBe(true);
			expect(service.getLastKnownDiagnostics(FILE)).toBeUndefined();
		});
	});
});

tests/clients/lsp/silent-clean-confirm.t:
/**
 * #799: a push-only server marked `silentOnClean` (`wait-policy/strategies.ts`)
 * publishes NOTHING on a clean file — there is no pull fallback and (unlike
 * typescript's tsserver sync commands, `tsserver-sync.ts`) no active
 * sync-confirm protocol either, so a clean touch used to burn its FULL wait
 * budget with zero signal either way and get reported `inconclusive`
 * (`diagnosticsTimedOut`), never `demonstratedReady`.
 *
 * `touchFile`'s generic clean-confirm gate (`clients/lsp/index.ts`, next to
 * the tsserver-specific sync-confirm block) closes that gap: a single-server
 * primary-scope touch whose notify write succeeded, whose wait ran its full
 * budget with no publish, and whose live capability snapshot classifies as
 * `tier3-silent` (`classifyCascadeWaitTier`, #458 — push-only AND
 * `silentOnClean`) is now CONFIRMED clean, not inconclusive. These tests
 * exercise that gate directly via `touchFile`, using marked push-only
 * strategies as concrete examples.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { hashDiagnosticContent } from "../../../clients/lsp/diagnostic-binding.js";
import { normalizeMapKey } from "../../../clients/path-utils.js";
import { removeTempDirSync } from "../test-utils.js";

const getServersForFileWithConfig = vi.fn();
const createLSPClient = vi.fn();
vi.mock("../../../clients/lsp/config.js", () => ({
	getServersForFileWithConfig,
	getServerInitOverride: vi.fn().mockReturnValue(undefined),
}));
vi.mock("../../../clients/lsp/client.js", () => ({ createLSPClient }));

function makeServer(id: string, ext: string, root: string) {
	return {
		id,
		name: id,
		extensions: [ext],
		idleEviction: "resident",
		root: async () => root,
		spawn: vi.fn(async () => ({ process: {}, source: "test" })),
	};
}

/**
 * A push-only client that NEVER publishes diagnostics (mirrors a clean
 * markdown file against marksman) — `waitForDiagnostics` always resolves
 * `undefined` right at its deadline, exactly like a real client's wait
 * timing out with nothing having arrived.
 */
function makeSilentPushOnlyClient(serverId: string, root: string) {
	const waitCalls: Array<{ filePath: string; ms: number }> = [];
	// #4532 gap 9: the double answers the touch gate the way a real client does.
	// `sent` is the record its own `notify.open` builds; a case that replaces
	// `notify.open` with its own fake must write the record itself (see the
	// "#1253" block). The double holds no queue, so nothing is in flight.
	const sent = new Map<string, { hash: string }>();
	const open = vi.fn(async (filePath: string, content: string) => {
		sent.set(filePath, { hash: hashDiagnosticContent(content) });
	});
	return {
		client: {
			isAlive: () => true,
			shutdown: async () => {},
			getWorkspaceDiagnosticsSupport: () => ({
				advertised: false,
				mode: "push-only" as const,
				diagnosticProviderKind: "none",
			}),
			getOperationSupport: () => ({}),
			getAdvertisedCommands: () => [],
			getRawCapabilityKeys: () => [],
			getLaunchVariant: () => undefined,
			serverId,
			root,
			getSentContent: (filePath: string) => sent.get(filePath),
			hasNotifyInFlight: () => false,
			notify: { open },
			waitForDiagnostics: vi.fn(async (filePath: string, ms: number) => {
				waitCalls.push({ filePath, ms });
				await new Promise<void>((resolve) => {
					const t = setTimeout(resolve, ms);
					t.unref?.();
				});
				return undefined;
			}),
			getDiagnostics: vi.fn(() => []),
			// #814: never-publishes means nothing lands in the per-file cache
			// either — the aggregate gate's "still outstanding" check reads this
			// (`getAllDiagnostics().has(normalizedPath)`), same as the real
			// client's `clearDiagnosticsForPath`-then-nothing-arrived state.
			getAllDiagnostics: vi.fn(() => new Map()),
			// #1277: defaults to alive (matches the real client's "healthy
			// server" case, and `pingLiveness?.() ?? true`'s fallback for older
			// mocks that omit it entirely) — individual wedged-server tests
			// override this to `vi.fn().mockResolvedValue(false)`.
			pingLiveness: vi.fn().mockResolvedValue(true),
		},
		waitCalls,
	};
}

/**
 * #814: a server that DOES answer — either with real findings or a confirmed
 * empty result — resolving quickly regardless of the requested wait budget
 * (mirrors a fast push/pull confirmation, like `service-touch-collect.test.ts`'s
 * canned-resolve mocks). `getAllDiagnostics` reports a fresh per-file entry
 * (the same cache the real client clears on notify and repopulates on a real
 * publish/pull), which is exactly the "answered" signal the aggregate gate's
 * still-outstanding check relies on.
 */
function makePublishingClient(
	serverId: string,
	root: string,
	filePath: string,
	diagnostics: unknown[],
) {
	return {
		isAlive: () => true,
		shutdown: async () => {},
		getWorkspaceDiagnosticsSupport: () => ({
			advertised: false,
			mode: "push-only" as const,
			diagnosticProviderKind: "none",
		}),
		getOperationSupport: () => ({}),
		getAdvertisedCommands: () => [],
		getRawCapabilityKeys: () => [],
		getLaunchVariant: () => undefined,
		serverId,
		root,
		notify: { open: vi.fn(async () => {}) },
		waitForDiagnostics: vi.fn().mockResolvedValue(undefined),
		getDiagnostics: vi.fn(() => diagnostics),
		getAllDiagnostics: vi.fn(
			() =>
				new Map([
					[normalizeMapKey(filePath), { diags: diagnostics, ts: Date.now() }],
				]),
		),
	};
}

describe("touchFile silent-clean push-only confirm (#799)", () => {
	let tmp: string;
	beforeEach(() => {
		vi.resetModules();
		getServersForFileWithConfig.mockReset();
		createLSPClient.mockReset();
		tmp = fs.mkdtempSync(path.join(os.tmpdir(), "pi-lens-lsp-silent-clean-"));
		// Flat, tiny diagnostics-wait budget so the mocked servers' real
		// waitForDiagnostics sleep resolves in ~50ms instead of paying marksman's
		// real 1500ms strategy budget — keeps these tests fast without changing
		// the gate under test (readEnvDiagnosticsWaitMs, index.ts).
		process.env.PI_LENS_LSP_DIAGNOSTICS_MAX_WAIT_MS = "50";
	});
	afterEach(() => {
		delete process.env.PI_LENS_LSP_DIAGNOSTICS_MAX_WAIT_MS;
		removeTempDirSync(tmp);
	});

	it("(a) a silent-clean push-only server (marksman) resolves quickly as CONFIRMED clean (0 diagnostics), not inconclusive", async () => {
		const filePath = path.join(tmp, "a.md");
		fs.writeFileSync(filePath, "# hi\n");
		const marksman = makeServer("marksman", ".md", tmp);
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".md") ? [marksman] : [],
		);
		const { client, waitCalls } = makeSilentPushOnlyClient("marksman", tmp);
		createLSPClient.mockResolvedValue(client);

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const service = new LSPService();

		const result = await service.touchFile(filePath, "# hi\n", {
			diagnostics: "document",
			collectDiagnostics: true,
			clientScope: "primary",
			source: "test",
		});

		// Confirmed clean: an empty array, and NOT flagged inconclusive.
		expect(Array.isArray(result?.diags)).toBe(true);
		expect(result?.diags).toHaveLength(0);
		expect((result as { inconclusive?: boolean }).inconclusive).toBeUndefined();
		expect(result?.confirmation).toBe("confirmed");

		// The env override (set in beforeEach) is what the wait actually pays
		// here — marksman's real 1500ms strategy budget is covered separately by
		// sweep-warmup.test.ts:128.
		expect(waitCalls.length).toBe(1);
		expect(waitCalls[0]!.ms).toBe(50);

		// A confirmed-clean touch marks the server demonstratedReady — proven
		// indirectly via ensureWarmForSweep treating a subsequent sweep as a
		// no-op (this is the #799 fix that stops repeat-sweep re-payment).
		const warmup = await service.ensureWarmForSweep(filePath);
		expect(warmup.performedWarmup).toBe(false);
		expect(warmup.failedServerIds).toEqual([]);
	});

	it("#3347: the newly marked lua strategy takes the tier-3 clean-confirm path", async () => {
		const filePath = path.join(tmp, "main.lua");
		fs.writeFileSync(filePath, "local value = 1\n");
		const lua = makeServer("lua", ".lua", tmp);
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".lua") ? [lua] : [],
		);
		const { client, waitCalls } = makeSilentPushOnlyClient("lua", tmp);
		createLSPClient.mockResolvedValue(client);

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const service = new LSPService();
		const result = await service.touchFile(filePath, "local value = 1\n", {
			diagnostics: "document",
			collectDiagnostics: true,
			clientScope: "primary",
			source: "test-3347-lua",
		});

		// Independent production-path effect: a tier-3 decision confirms clean
		// despite the silent wait, and the requested strategy budget is passed to
		// the client instead of an unbounded fallback.
		expect(result?.confirmation).toBe("confirmed");
		expect(result?.diags).toEqual([]);
		expect(waitCalls).toHaveLength(1);
		expect(waitCalls[0]!.ms).toBe(50);
	});

	it("#1277: a WEDGED marksman (accepts the notify write, then never answers anything) stays INCONCLUSIVE, not confirmed clean", async () => {
		const filePath = path.join(tmp, "a.md");
		fs.writeFileSync(filePath, "# hi\n");
		const marksman = makeServer("marksman", ".md", tmp);
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".md") ? [marksman] : [],
		);
		const { client } = makeSilentPushOnlyClient("marksman", tmp);
		// The notify write is accepted (resolves normally) and the capability
		// snapshot still classifies this touch as tier3-silent — identical to
		// the genuinely-clean case in test (a) above. The only difference is
		// the server is wedged: it never answers ANY request, including the
		// #1277 liveness ping added by this gate. Pre-#1277 there was nothing
		// checking this and the touch would confirm clean anyway.
		client.pingLiveness = vi.fn().mockResolvedValue(false);
		createLSPClient.mockResolvedValue(client);

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const service = new LSPService();

		const result = await service.touchFile(filePath, "# hi\n", {
			diagnostics: "document",
			collectDiagnostics: true,
			clientScope: "primary",
			source: "test",
		});

		expect((result as { inconclusive?: boolean }).inconclusive).toBe(true);
		expect(result?.confirmation).toBeUndefined();
		expect(client.pingLiveness).toHaveBeenCalled();
	});

	it("a non-primary/multi-server touch does NOT take the SINGLE-SERVER silent-clean shortcut (stays inconclusive, matching pre-#799 behavior)", async () => {
		const filePath = path.join(tmp, "a.md");
		fs.writeFileSync(filePath, "# hi\n");
		const marksman = makeServer("marksman", ".md", tmp);
		const typos = makeServer("typos", ".md", tmp);
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".md") ? [marksman, typos] : [],
		);
		createLSPClient.mockImplementation(async (opts: { serverId: string }) => {
			return makeSilentPushOnlyClient(opts.serverId, tmp).client;
		});

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const service = new LSPService();

		const result = await service.touchFile(filePath, "# hi\n", {
			diagnostics: "document",
			collectDiagnostics: true,
			clientScope: "all",
			source: "test",
		});

		// This #799 gate is scoped to `spawned.length === 1` and never fires
		// here. #814's generalized `clientScope: "all"` gate (see the describe
		// block below) DOES now consider multi-server "all" touches — but it
		// only resolves early when EVERY still-outstanding server is tier3-
		// silent, and `typos` is an ordinary push-only server (not marked
		// `silentOnClean`), so this touch still correctly stays inconclusive
		// rather than wrongly treating typos' silence as confirmed-clean.
		expect((result as { inconclusive?: boolean }).inconclusive).toBe(true);
	});
});

describe("touchFile capability-aware AGGREGATE wait (#814)", () => {
	let tmp: string;
	beforeEach(() => {
		vi.resetModules();
		getServersForFileWithConfig.mockReset();
		createLSPClient.mockReset();
		tmp = fs.mkdtempSync(
			path.join(os.tmpdir(), "pi-lens-lsp-silent-clean-agg-"),
		);
		// Flat, tiny diagnostics-wait budget so the mocked servers' real
		// waitForDiagnostics sleep resolves in ~50ms instead of paying their real
		// (1000-1500ms) strategy budgets — keeps these tests fast without
		// changing the gate under test (readEnvDiagnosticsWaitMs, index.ts).
		process.env.PI_LENS_LSP_DIAGNOSTICS_MAX_WAIT_MS = "50";
	});
	afterEach(() => {
		vi.useRealTimers();
		delete process.env.PI_LENS_LSP_DIAGNOSTICS_MAX_WAIT_MS;
		removeTempDirSync(tmp);
	});

	it("(a) scope-all: one server publishes, the silent one doesn't — resolves as CONFIRMED clean (not inconclusive), publisher's diagnostics kept", async () => {
		const filePath = path.join(tmp, "a.md");
		fs.writeFileSync(filePath, "# hi\n");
		const marksman = makeServer("marksman", ".md", tmp);
		const typos = makeServer("typos", ".md", tmp);
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".md") ? [marksman, typos] : [],
		);
		const finding = {
			severity: 2 as const,
			message: "possible typo",
			range: {
				start: { line: 0, character: 2 },
				end: { line: 0, character: 4 },
			},
			source: "typos",
		};
		const attributedFinding = { ...finding, serverId: "typos" };
		createLSPClient.mockImplementation(async (opts: { serverId: string }) => {
			if (opts.serverId === "typos") {
				return makePublishingClient("typos", tmp, filePath, [finding]);
			}
			return makeSilentPushOnlyClient(opts.serverId, tmp).client;
		});

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const service = new LSPService();

		const result = await service.touchFile(filePath, "# hi\n", {
			diagnostics: "document",
			collectDiagnostics: true,
			clientScope: "all",
			source: "lens_diagnostics_full",
		});

		expect((result as { inconclusive?: boolean }).inconclusive).toBeUndefined();
		expect(result?.confirmation).toBe("confirmed");
		expect(result?.diags).toEqual([attributedFinding]);
	});

	it("#1277: scope-all — the still-outstanding silent server is WEDGED (fails the liveness ping), so the touch stays INCONCLUSIVE even though the publishing sibling answered", async () => {
		const filePath = path.join(tmp, "a.md");
		fs.writeFileSync(filePath, "# hi\n");
		const marksman = makeServer("marksman", ".md", tmp);
		const typos = makeServer("typos", ".md", tmp);
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".md") ? [marksman, typos] : [],
		);
		const finding = {
			severity: 2 as const,
			message: "possible typo",
			range: {
				start: { line: 0, character: 2 },
				end: { line: 0, character: 4 },
			},
			source: "typos",
		};
		createLSPClient.mockImplementation(async (opts: { serverId: string }) => {
			if (opts.serverId === "typos") {
				return makePublishingClient("typos", tmp, filePath, [finding]);
			}
			// marksman: notify write accepted, wait times out with nothing
			// published (identical to the genuinely-clean case in test (a)
			// above) — but it is wedged, so the #1277 liveness ping never
			// answers either.
			const { client } = makeSilentPushOnlyClient("marksman", tmp);
			client.pingLiveness = vi.fn().mockResolvedValue(false);
			return client;
		});

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const service = new LSPService();

		const result = await service.touchFile(filePath, "# hi\n", {
			diagnostics: "document",
			collectDiagnostics: true,
			clientScope: "all",
			source: "lens_diagnostics_full",
		});

		expect((result as { inconclusive?: boolean }).inconclusive).toBe(true);
		expect(result?.confirmation).toBeUndefined();
	});

	it("(b) scope-all: the silent server's notify write TIMED OUT — falls back to today's timeout/inconclusive behavior", async () => {
		const prev = process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS;
		process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS = "50";
		try {
			const filePath = path.join(tmp, "a.md");
			fs.writeFileSync(filePath, "# hi\n");
			const marksman = makeServer("marksman", ".md", tmp);
			const typos = makeServer("typos", ".md", tmp);
			getServersForFileWithConfig.mockImplementation((fp: string) =>
				fp.endsWith(".md") ? [marksman, typos] : [],
			);
			const finding = {
				severity: 2 as const,
				message: "possible typo",
				range: {
					start: { line: 0, character: 2 },
					end: { line: 0, character: 4 },
				},
				source: "typos",
			};
			createLSPClient.mockImplementation(async (opts: { serverId: string }) => {
				if (opts.serverId === "typos") {
					return makePublishingClient("typos", tmp, filePath, [finding]);
				}
				// marksman's notify.open never resolves — the write itself
				// never lands, so its silence has no basis to be read as
				// "saw the file and stayed quiet because it's clean".
				const { client } = makeSilentPushOnlyClient("marksman", tmp);
				client.notify.open = vi.fn(() => new Promise(() => {}));
				return client;
			});

			const { LSPService } = await import("../../../clients/lsp/index.js");
			const service = new LSPService();

			const result = await service.touchFile(filePath, "# hi\n", {
				diagnostics: "document",
				collectDiagnostics: true,
				clientScope: "all",
				source: "lens_diagnostics_full",
			});

			expect((result as { inconclusive?: boolean }).inconclusive).toBe(true);
			expect(result?.confirmation).toBeUndefined();
		} finally {
			if (prev === undefined) delete process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS;
			else process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS = prev;
		}
	});

	it("(c) scope-all: an ordinary push-only (non-silentOnClean) straggler still runs to cap and stays inconclusive — no behavior change", async () => {
		const filePath = path.join(tmp, "a.md");
		fs.writeFileSync(filePath, "# hi\n");
		const marksman = makeServer("marksman", ".md", tmp);
		const typos = makeServer("typos", ".md", tmp);
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".md") ? [marksman, typos] : [],
		);
		// Both servers are silent — marksman IS tier3-silent, but typos is an
		// ordinary push-only server (no `silentOnClean` marker in
		// wait-policy/strategies.ts), so its silence is genuinely ambiguous and must
		// not be treated as confirmed-clean.
		createLSPClient.mockImplementation(async (opts: { serverId: string }) => {
			return makeSilentPushOnlyClient(opts.serverId, tmp).client;
		});

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const service = new LSPService();

		const result = await service.touchFile(filePath, "# hi\n", {
			diagnostics: "document",
			collectDiagnostics: true,
			clientScope: "all",
			source: "lens_diagnostics_full",
		});

		expect((result as { inconclusive?: boolean }).inconclusive).toBe(true);
		const { getDegradationSummary } =
			await import("../../../clients/degradation-ledger.js");
		expect(getDegradationSummary()).toEqual([
			expect.objectContaining({
				kind: "lsp-diagnostics-timeout",
				count: 2,
				latestReasons: expect.arrayContaining([
					expect.objectContaining({ subject: "marksman" }),
					expect.objectContaining({ subject: "typos" }),
				]),
			}),
		]);
	});

	it("(d) scope-all: EVERY spawned server is silent+tier3-silent — resolves at the max of their budgets as CONFIRMED clean", async () => {
		// This test asserts the REAL per-server strategy budgets (marksman
		// 1500ms, typescript 1000ms) are what get paid — undo the describe's
		// env override so it isn't flattened to 50ms like its siblings.
		delete process.env.PI_LENS_LSP_DIAGNOSTICS_MAX_WAIT_MS;
		const filePath = path.join(tmp, "a.ts");
		fs.writeFileSync(filePath, "const x = 1;\n");
		const marksman = makeServer("marksman", ".ts", tmp);
		const typescript = makeServer("typescript", ".ts", tmp);
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".ts") ? [marksman, typescript] : [],
		);
		createLSPClient.mockImplementation(async (opts: { serverId: string }) => {
			return makeSilentPushOnlyClient(opts.serverId, tmp).client;
		});

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const service = new LSPService();

		// The stubs' silent waits sleep on the faked setTimeout; setImmediate
		// stays real so the touch's own file I/O can interleave with the pump.
		vi.useFakeTimers({ toFake: ["setTimeout", "clearTimeout", "Date"] });
		const startedAt = Date.now();
		let finishedAt: number | undefined;
		const touch = service
			.touchFile(filePath, "const x = 1;\n", {
				diagnostics: "document",
				collectDiagnostics: true,
				clientScope: "all",
				source: "lens_diagnostics_full",
			})
			.then((settled) => {
				finishedAt = Date.now();
				return settled;
			});
		for (let step = 0; step < 100 && finishedAt === undefined; step++) {
			await vi.advanceTimersByTimeAsync(50);
			await new Promise((resolve) => setImmediate(resolve));
		}
		const result = await touch;
		const elapsedMs = (finishedAt ?? Number.NaN) - startedAt;

		expect(Array.isArray(result?.diags)).toBe(true);
		expect(result?.diags).toHaveLength(0);
		expect((result as { inconclusive?: boolean }).inconclusive).toBeUndefined();
		expect(result?.confirmation).toBe("confirmed");
		// marksman (1500ms) and typescript (1000ms) — the touch waits for the
		// SLOWER of the two (marksman), not a shortened window.
		expect(elapsedMs).toBeGreaterThanOrEqual(1490);
	});

	it("(e) scope-all: classification throws — fails safe to today's timeout/inconclusive behavior", async () => {
		const filePath = path.join(tmp, "a.md");
		fs.writeFileSync(filePath, "# hi\n");
		const marksman = makeServer("marksman", ".md", tmp);
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".md") ? [marksman] : [],
		);
		createLSPClient.mockImplementation(async () => {
			const { client } = makeSilentPushOnlyClient("marksman", tmp);
			// Force the capability-snapshot probe (`getCapabilitySnapshots`,
			// which reads `getAdvertisedCommands()` per live client) to throw —
			// the gate's try/catch must fail safe to today's inconclusive
			// behavior rather than propagating the error.
			client.getAdvertisedCommands = () => {
				throw new Error("boom");
			};
			return client;
		});

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const service = new LSPService();

		const result = await service.touchFile(filePath, "# hi\n", {
			diagnostics: "document",
			collectDiagnostics: true,
			clientScope: "all",
			source: "lens_diagnostics_full",
		});

		expect((result as { inconclusive?: boolean }).inconclusive).toBe(true);
	});
});

/**
 * #1253: the touch debounce must not launder a FAILED notify write into a
 * later touch that looks fully delivered.
 *
 * `markTouched` records "these servers already have this content", and
 * `shouldSkipNotify` reads that record to skip the next touch's notify
 * entirely — which also leaves that next touch's `notifyWriteTimedOut` false.
 * Both silent-clean gates (#799 single-server, #814 aggregate) treat
 * `!notifyWriteTimedOut` as proof the server SAW the content, so recording a
 * write that never landed turned a silent server's ignorance into a confirmed
 * clean one debounce window later. Since #1253 that confirmation is carried
 * all the way out to `lsp_diagnostics` (`TouchFileResult.confirmation`), so
 * the laundering surfaces as a false "clean" file rather than being absorbed
 * by the tool's own unconfirmed fallback.
 */
describe("touch debounce after a failed notify write (#1253)", () => {
	let tmp: string;
	let prevNotifyBudget: string | undefined;
	beforeEach(() => {
		vi.resetModules();
		getServersForFileWithConfig.mockReset();
		createLSPClient.mockReset();
		tmp = fs.mkdtempSync(
			path.join(os.tmpdir(), "pi-lens-lsp-silent-clean-debounce-"),
		);
		process.env.PI_LENS_LSP_DIAGNOSTICS_MAX_WAIT_MS = "50";
		prevNotifyBudget = process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS;
		process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS = "50";
	});
	afterEach(() => {
		delete process.env.PI_LENS_LSP_DIAGNOSTICS_MAX_WAIT_MS;
		if (prevNotifyBudget === undefined) {
			delete process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS;
		} else {
			process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS = prevNotifyBudget;
		}
		removeTempDirSync(tmp);
	});

	it("re-pushes (and stays inconclusive) instead of debouncing into a silent-clean confirm", async () => {
		const filePath = path.join(tmp, "a.md");
		fs.writeFileSync(filePath, "# hi\n");
		const marksman = makeServer("marksman", ".md", tmp);
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".md") ? [marksman] : [],
		);
		const { client } = makeSilentPushOnlyClient("marksman", tmp);
		// Every write stalls past the notify budget — the server never receives
		// the file, so its silence is never evidence of "clean".
		const open = vi.fn(() => new Promise(() => {}));
		client.notify.open = open as never;
		createLSPClient.mockResolvedValue(client);

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const service = new LSPService();

		const options = {
			diagnostics: "document" as const,
			collectDiagnostics: true as const,
			clientScope: "primary" as const,
			source: "test",
		};
		const first = await service.touchFile(filePath, "# hi\n", options);
		// Same content, well inside the 1500ms debounce window.
		const second = await service.touchFile(filePath, "# hi\n", options);

		expect((first as { inconclusive?: boolean }).inconclusive).toBe(true);
		expect(first?.confirmation).toBeUndefined();
		// The second touch must attempt the write again rather than assume the
		// first one landed.
		expect(open).toHaveBeenCalledTimes(2);
		expect((second as { inconclusive?: boolean }).inconclusive).toBe(true);
		expect(second?.confirmation).toBeUndefined();
	});

	it("still debounces the notify after a write that DID land", async () => {
		const filePath = path.join(tmp, "a.md");
		fs.writeFileSync(filePath, "# hi\n");
		const marksman = makeServer("marksman", ".md", tmp);
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".md") ? [marksman] : [],
		);
		const { client } = makeSilentPushOnlyClient("marksman", tmp);
		// The landed write records the bytes it carried, as the real client does.
		const sent = new Map<string, { hash: string }>();
		const open = vi.fn(async (filePath: string, content: string) => {
			sent.set(filePath, { hash: hashDiagnosticContent(content) });
		});
		client.notify.open = open as never;
		(client as { getSentContent?: unknown }).getSentContent = (
			filePath: string,
		) => sent.get(filePath);
		createLSPClient.mockResolvedValue(client);

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const service = new LSPService();

		const options = {
			diagnostics: "document" as const,
			collectDiagnostics: true as const,
			clientScope: "primary" as const,
			source: "test",
		};
		const first = await service.touchFile(filePath, "# hi\n", options);
		const second = await service.touchFile(filePath, "# hi\n", options);

		// One delivered push is enough for the debounce window — unchanged.
		expect(open).toHaveBeenCalledTimes(1);
		expect(first?.confirmation).toBe("confirmed");
		expect(second?.confirmation).toBe("confirmed");
	});
});

tests/clients/lsp/touch-debounce-content:
/**
 * #4532 gap 9 — the touch debounce must decide by the bytes the client holds,
 * not by how long ago the last push was.
 *
 * Recurrence this file prevents: `shouldSkipNotify` gated the "same content
 * was already pushed" skip on `now - previous.touchedAt <= TOUCH_DEBOUNCE_MS`
 * and only then compared fingerprints. A touch whose own work outlived the
 * window (an auxiliary spawn, a paced scanner write) made the NEXT touch of
 * byte-identical content look stale by elapsed time alone, so the identical
 * bytes went out again — and a `didChange` on unchanged content clears the
 * server's cached diagnostics and restarts computation (#4527 measured the
 * equivalent re-push as a 2335 ms cold `lsp_diagnostics_timeout` on clangd,
 * which does not republish for identical bytes).
 *
 * Everything here is the production path: the real `LSPService`, the real
 * client (whose own sent-content record is the evidence the gate must read),
 * the real per-document notify queue, and a real stdio JSON-RPC wire to the
 * shared fake LSP child. Only the server binary is a fake, and the trace is
 * the witness: "no push" means the SERVER received nothing, not that pi-lens
 * skipped its own bookkeeping.
 */

import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { hashDiagnosticContent } from "../../../clients/lsp/diagnostic-binding.js";
import {
	resetProjectTrust,
	setProjectTrustState,
} from "../../../clients/project-trust.js";
import {
	cleanupTestEnvironmentsDrained,
	setupTestEnvironment,
} from "../test-utils.js";

// `clients/lsp/index.js` reads this once at module load, so it is set before
// any import of that module is evaluated (every load below is dynamic).
vi.hoisted(() => {
	process.env.PI_LENS_LSP_TOUCH_DEBOUNCE_MS = "150";
});

const fakeServer = fileURLToPath(
	new URL("../../fixtures/fake-lsp-server.mjs", import.meta.url),
);
const PREFIX = "pi-lens-4532-touch-debounce-";
const env = setupTestEnvironment(PREFIX);
/** The window the fix must stop deciding by. */
const WINDOW_MS = 150;
const TOUCH = {
	diagnostics: "none",
	clientScope: "primary",
	source: "lsp_sync",
} as const;
const HELD = "export const held = 1;\n";
const CHANGED = "export const held = 2;\n";

let dir = "";
let traceFile = "";

async function service() {
	const lsp = await import("../../../clients/lsp/index.js");
	return lsp.getLSPService();
}

function traceLines(): string[] {
	return fs.existsSync(traceFile)
		? fs.readFileSync(traceFile, "utf8").split("\n").filter(Boolean)
		: [];
}

/**
 * Ask the server for an answer now, then return the trace length. The child
 * reads stdin in order over one ordered stream, so every notification written
 * before this call is traced before the request is answered; a plain read of
 * the trace races the child process. The request's own line is filtered out by
 * {@link documents}.
 */
async function fence(file: string): Promise<number> {
	await (await service()).documentSymbol(file);
	return traceLines().length;
}

const uri = (file: string) => pathToFileURL(file).href;

/** Document notifications only: the wire's answer to "did the server get it". */
const documents = (lines: readonly string[]) =>
	lines.filter((line) =>
		/^recv textDocument\/did(Open|Change|Save|Close) /.test(line),
	);

/** The didSave notifications only. */
const saves = (lines: readonly string[]) =>
	lines.filter((line) => line.startsWith("recv textDocument/didSave "));

/** What each didOpen/didChange carried, as the fake server's 12-hex sha. */
const texts = (lines: readonly string[]) =>
	lines.filter((line) => line.startsWith("text "));

/** The bytes a didOpen/didChange carried, as the fake server traced them. */
const textLine = (file: string, content: string) =>
	`text ${uri(file)} ${createHash("sha256")
		.update(content)
		.digest("hex")
		.slice(0, 12)}`;

/**
 * Run `act` with the clock already past the debounce window. Only `Date` is
 * faked — the notify queue's real timers, the stdio wire and the child process
 * keep running — so the window is exceeded without a sleep and without holding
 * a real timeout, and the assertion is about content, never about time.
 */
async function pastWindow(act: () => Promise<unknown>): Promise<void> {
	vi.useFakeTimers({ toFake: ["Date"], now: Date.now() + WINDOW_MS * 10 });
	try {
		await act();
	} finally {
		vi.useRealTimers();
	}
}

function pathFor(tag: string): string {
	return path.join(dir, `${tag}.ts`);
}

describe("#4532 gap 9 — the touch debounce reads the client's content record", () => {
	beforeAll(async () => {
		setProjectTrustState("trusted");
		dir = path.join(env.tmpDir, "proj");
		fs.mkdirSync(path.join(dir, ".pi-lens"), { recursive: true });
		fs.writeFileSync(path.join(dir, "package.json"), "{}\n");
		// Every fixture file exists BEFORE the client starts, so the client
		// announces it as Changed rather than Created. A Created this client sent
		// since the push legitimately re-pushes the same bytes (#4320), and those
		// cases are separate; this file is about the content gate alone.
		for (const tag of [
			"warm",
			"identical",
			"changed",
			"reopened",
			"race",
			"saved",
		])
			fs.writeFileSync(pathFor(tag), HELD);
		traceFile = path.join(env.tmpDir, "wire.trace");
		const shim = path.join(env.tmpDir, "server.mjs");
		fs.writeFileSync(
			shim,
			[
				'process.env.FAKE_LSP_NO_DIAGNOSTIC_PROVIDER = "1";',
				'process.env.FAKE_LSP_TRACE_TEXT = "1";',
				// A save-triggered server (#3405): declares textDocumentSync.save, so
				// `notify.save` reaches the wire and the trace can witness it.
				'process.env.FAKE_LSP_SAVE = "true";',
				`process.env.FAKE_LSP_TRACE_FILE = ${JSON.stringify(traceFile)};`,
				`import(${JSON.stringify(pathToFileURL(fakeServer).href)});`,
				"",
			].join("\n"),
		);
		fs.writeFileSync(
			path.join(dir, ".pi-lens", "lsp.json"),
			JSON.stringify({
				servers: {
					"fake-ts": {
						name: "fake",
						extensions: [".ts"],
						command: process.execPath,
						args: [shim],
						rootMarkers: ["package.json"],
					},
				},
				disabledServers: [
					"typescript",
					"deno",
					"python",
					"python-jedi",
					"opengrep",
					"ast-grep",
					"typos",
				],
			}),
		);
		const config = await import("../../../clients/lsp/config.js");
		await config.initLSPConfig(dir);
		// Start the one client this project needs with its start stamp a few
		// seconds AFTER the fixture file births, so `watchedTypeForOpen` reads
		// them as files the server already knew (its margin is 100 ms). Only
		// `Date` is faked: the spawn, the handshake and the wire stay real.
		vi.useFakeTimers({ toFake: ["Date"], now: Date.now() + 4000 });
		try {
			await (await service()).documentSymbol(pathFor("warm"));
		} finally {
			vi.useRealTimers();
		}
	});

	afterAll(async () => {
		await cleanupTestEnvironmentsDrained(PREFIX, {
			beforeDrain: async () => {
				await (await service()).shutdown();
			},
		});
		resetProjectTrust();
	});

	// The defect: identical bytes, pushed once, then offered again after the
	// window. Pre-fix the second offer re-pushed them and cleared the server's
	// diagnostics for content it already had.
	it("leaves the server's bytes alone when only the elapsed window has passed", async () => {
		const svc = await service();
		const file = pathFor("identical");
		const opened = traceLines().length;
		await svc.touchFile(file, HELD, TOUCH);
		const firstPush = await fence(file);
		expect(documents(traceLines().slice(opened))).toEqual([
			`recv textDocument/didOpen ${uri(file)}`,
		]);
		// The gate's own evidence: the client records holding exactly these bytes.
		expect(svc.getTrackedContent(file, dir)?.hash).toBe(
			hashDiagnosticContent(HELD),
		);

		await pastWindow(() => svc.touchFile(file, HELD, TOUCH));

		const secondPush = await fence(file);
		expect(documents(traceLines().slice(firstPush, secondPush))).toEqual([]);
	});

	// The other direction of the same gate: a content record that disagrees
	// with the bytes must still push after the window.
	it("pushes changed bytes after the window", async () => {
		const svc = await service();
		const file = pathFor("changed");
		await svc.touchFile(file, HELD, TOUCH);
		const mark = await fence(file);

		fs.writeFileSync(file, CHANGED);
		await pastWindow(() => svc.touchFile(file, CHANGED, TOUCH));

		await fence(file);
		const lines = traceLines().slice(mark);
		expect(documents(lines)).toEqual([
			`recv textDocument/didChange ${uri(file)}`,
		]);
		expect(texts(lines)).toEqual([textLine(file, CHANGED)]);
		expect(svc.getTrackedContent(file, dir)?.hash).toBe(
			hashDiagnosticContent(CHANGED),
		);
	});

	// #4532 gap 9 F2: the save mark belongs to the bytes its didSave went out
	// for. `openFile` is the second writer of the client's record (the
	// resync-on-past-EOF route), and it marks no touch, so the record advances
	// while the save mark still describes the older bytes. A saved touch of the
	// new bytes is debounced, and its save must still reach the wire.
	it("sends the save a skipped touch still owes after another writer advanced the record", async () => {
		const svc = await service();
		const file = pathFor("saved");
		const saved = { ...TOUCH, saved: true };
		await svc.touchFile(file, HELD, saved);
		const mark = await fence(file);
		expect(saves(traceLines().slice(0, mark))).toEqual([
			`recv textDocument/didSave ${uri(file)}`,
		]);

		// The resync route pushes directly: no `markTouched`, so the save mark
		// still names HELD while the record now names CHANGED.
		await svc.openFile(file, CHANGED);
		await fence(file);
		await pastWindow(() => svc.touchFile(file, CHANGED, saved));

		await fence(file);
		const lines = traceLines().slice(mark);
		expect(saves(lines)).toEqual([`recv textDocument/didSave ${uri(file)}`]);
	});

	// A document closed and reopened inside the window: didClose drops the
	// client's record, so nothing proves the server still holds the bytes and
	// the reopen must push.
	it("pushes a document again after it was closed and reopened", async () => {
		const svc = await service();
		const file = pathFor("reopened");
		await svc.touchFile(file, HELD, TOUCH);
		const entry = await svc.getClientForFile(file);
		expect(
			entry?.client,
			"the case needs the file's live client",
		).toBeDefined();
		const mark = await fence(file);

		// F5: hold the clock INSIDE the window for the skip decision, so the case
		// keeps reding the pre-#4532 gate. Without this a worker pause longer than
		// the window makes the old gate push normally and the guard passes on the
		// code it exists to catch.
		vi.useFakeTimers({ toFake: ["Date"], now: Date.now() + 1 });
		try {
			await entry!.client.closeDocument(file);
			await svc.touchFile(file, HELD, TOUCH);
		} finally {
			vi.useRealTimers();
		}

		await fence(file);
		const lines = traceLines().slice(mark);
		expect(documents(lines)).toEqual([
			`recv textDocument/didClose ${uri(file)}`,
			`recv textDocument/didOpen ${uri(file)}`,
		]);
		expect(texts(lines)).toEqual([textLine(file, HELD)]);
	});
});

tests/clients/lsp/touch-debounce-fingerp:
/**
 * #3480: the touch debounce must tell two long documents apart when they
 * differ only in the middle.
 *
 * Recurrence this file prevents: `shouldSkipNotify` compared a length + first
 * 48 + last 48 chars fingerprint, so a same-length middle edit of a >96-char
 * file inside the 1500 ms debounce window was skipped with nothing recorded,
 * and the server kept answering from the previous content.
 *
 * Production chain: the REAL `LSPService.touchFile` -> the REAL
 * `handleNotifyOpen` notify queue -> a mock `MessageConnection` (the process
 * boundary). Only the server registry and client construction are doubled.
 */

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import * as clientModule from "../../../clients/lsp/client.js";
import { hashDiagnosticContent } from "../../../clients/lsp/diagnostic-binding.js";
import { normalizeMapKey } from "../../../clients/path-utils.js";
import { fingerprintDocumentContent } from "../../../clients/lsp/document-drift.js";
import { LSPService } from "../../../clients/lsp/index.js";
import { waitFor } from "../interleaving-kit.js";
import { createMockState } from "./mock-client-state.js";

const { getServersForFileWithConfig, createLSPClient } = vi.hoisted(() => ({
	getServersForFileWithConfig: vi.fn(),
	createLSPClient: vi.fn(),
}));

vi.mock("../../../clients/lsp/config.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../../clients/lsp/config.js")>()),
	getServersForFileWithConfig,
	getServerInitOverride: vi.fn().mockReturnValue(undefined),
}));
// #3480 round 1: count the fingerprints `touchFile` computes. Wrapped, not
// replaced: every other export is the real module.
vi.mock("../../../clients/lsp/document-drift.js", async (importOriginal) => {
	const actual =
		await importOriginal<
			typeof import("../../../clients/lsp/document-drift.js")
		>();
	return {
		...actual,
		fingerprintDocumentContent: vi.fn(actual.fingerprintDocumentContent),
	};
});
vi.mock("../../../clients/lsp/client.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../../clients/lsp/client.js")>()),
	createLSPClient,
}));

const ROOT = "/repo";
const FILE = "/repo/long.ts";
const HEAD = `// ${"h".repeat(60)}\n`;
const TAIL = `// ${"t".repeat(60)}\n`;
const A = `${HEAD}const x = 1;\n${TAIL}`;
const B = `${HEAD}const x = 2;\n${TAIL}`;

/**
 * One event-loop tick. The notify queue advances on this loop's microtask
 * chain once a held send is released, which is the safe custom yield
 * `tests/clients/interleaving-kit.ts` documents for `waitFor` (never a worker
 * or child process, which `setImmediate` cannot observe).
 */
const tick = () => new Promise<void>((resolve) => setImmediate(resolve));

/** Wait for a path's notify queue to drain through its promise chain. */
const queueDrained = (state: ReturnType<typeof createMockState>) =>
	waitFor(
		() => state.notifyChangeQueues.size,
		(size) => size === 0,
		{ timeoutMs: 2_000, yieldControl: tick },
	);

/**
 * `reportRecord: false` builds the client shape #4532 gap 9 F3 is about: one
 * that cannot say what it holds. `reportQueue: false` is the other unanswerable
 * question — a record but no word on whether a send for the path is still to
 * come. Production has neither, so a double is the only way to reach either
 * branch, and the gate must fail CLOSED on both.
 */
async function setup(
	options: { reportRecord?: boolean; reportQueue?: boolean } = {},
) {
	const state = createMockState({ root: ROOT, serverId: "typescript" });
	// The server declared `save`, so a standalone `notify.save` reaches the wire
	// and the save mark means something (#3405).
	state.saveOptions = { includeText: false };
	const client = {
		serverId: "typescript",
		root: ROOT,
		customServer: false,
		isAlive: () => true,
		shutdown: async () => {},
		getWorkspaceDiagnosticsSupport: () => ({
			advertised: false,
			mode: "push-only" as const,
			diagnosticProviderKind: "none",
		}),
		getOperationSupport: () => ({}),
		getSaveOptions: () => ({ includeText: false }),
		getAdvertisedCommands: () => [],
		getRawCapabilityKeys: () => [],
		getLaunchVariant: () => undefined,
		diagnosticsVersion: 0,
		getDiagnosticsVersionForPath: vi.fn(() => 0),
		getDiagnostics: vi.fn(() => []),
		getAllDiagnostics: vi.fn(() => new Map()),
		getDiagnosticBinding: vi.fn(() => undefined),
		// #4532: the real readers over this double's real state, so the gate's
		// evidence is the queue and record the fixture actually drives. Omitting
		// both is the F3 shape: a client that cannot report a record.
		...(options.reportRecord === false
			? {}
			: {
					getSentContent: (filePath: string) => {
						// Read over the fixture's REAL state — `recordSentContent` writes this
						// map, and `clientModule.sentContentFor` is the same read. Spelled
						// here instead of imported so this fixture also runs against the code
						// before that reader existed, which the F1 red-first proof needs.
						const sent = state.documentContentHashes.get(
							normalizeMapKey(filePath),
						);
						return sent && { hash: sent.hash };
					},
				}),
		...(options.reportQueue === false
			? {}
			: {
					hasNotifyInFlight: (filePath: string) =>
						clientModule.hasNotifyInFlightFor(state, filePath),
				}),
		notify: {
			announceCreated: () => undefined,
			save: (filePath: string) =>
				clientModule.handleNotifySave(state, filePath),
			open: (
				filePath: string,
				content: string,
				languageId: string,
				preserveDiagnostics?: boolean,
				silent?: boolean,
				saved?: boolean,
			) =>
				clientModule.handleNotifyOpen(
					state,
					filePath,
					content,
					languageId,
					preserveDiagnostics,
					silent,
					saved,
				),
			change: vi.fn(async () => {}),
			close: vi.fn(async () => {}),
		},
		pingLiveness: vi.fn().mockResolvedValue(true),
		waitForDiagnostics: vi.fn(async () => {}),
	};
	getServersForFileWithConfig.mockReturnValue([
		{
			id: "typescript",
			name: "typescript",
			extensions: [".ts"],
			idleEviction: "resident",
			root: async () => ROOT,
			spawn: vi.fn(async () => ({ process: {}, source: "test" })),
		},
	]);
	createLSPClient.mockResolvedValue(client);
	const service = new LSPService();
	const texts = () =>
		vi
			.mocked(state.connection.sendNotification)
			.mock.calls.filter(([method]) =>
				/^textDocument\/(didOpen|didChange)$/.test(String(method)),
			)
			.map(([method, params]) => {
				const p = params as {
					textDocument?: { text?: string };
					contentChanges?: Array<{ text: string }>;
				};
				return `${String(method).replace("textDocument/", "")}:${
					p.textDocument?.text ?? p.contentChanges?.at(-1)?.text
				}`;
			});
	return { service, texts, state, client };
}

describe("#3480 — touch debounce fingerprint covers the whole document", () => {
	beforeEach(() => {
		getServersForFileWithConfig.mockReset();
		createLSPClient.mockReset();
	});
	afterEach(() => {
		vi.restoreAllMocks();
	});

	it("sends a same-length middle edit of a long file inside the debounce window", async () => {
		expect(B.length).toBe(A.length);
		expect(A.length).toBeGreaterThan(96);
		const { service, texts } = await setup();

		await service.touchFile(FILE, A, { diagnostics: "none", source: "test" });
		await service.touchFile(FILE, B, { diagnostics: "none", source: "test" });

		expect(texts()).toEqual([`didOpen:${A}`, `didChange:${B}`]);
	});

	// #3480 round 1 N1: one whole-content hash per touch, not one per debounce
	// check and per mark (each a sha256 of up to the whole file).
	it("fingerprints the content once per touch", async () => {
		const { service } = await setup();
		await service.touchFile(FILE, A, { diagnostics: "none", source: "test" });
		const fingerprint = vi.mocked(fingerprintDocumentContent);
		fingerprint.mockClear();

		await service.touchFile(FILE, B, { diagnostics: "none", source: "test" });

		expect(fingerprint.mock.calls.filter(([c]) => c === B)).toHaveLength(1);
	});

	it("still skips a repeat touch of identical long content inside the window", async () => {
		const { service, texts } = await setup();

		await service.touchFile(FILE, A, { diagnostics: "none", source: "test" });
		await service.touchFile(FILE, A, { diagnostics: "none", source: "test" });

		expect(texts()).toEqual([`didOpen:${A}`]);
	});

	// #4532 gap 9 F3: a client that cannot report its record has an UNKNOWN
	// final state, and the pre-#4532 window gate that used to decide for it is
	// the one `GateWindowReopen` proves can leave a server holding no document
	// at all (`formal/lsp-server-content`). So it pushes, every time.
	it("always pushes a client that cannot report the record it holds", async () => {
		const { service, texts } = await setup({ reportRecord: false });

		await service.touchFile(FILE, A, { diagnostics: "none", source: "test" });
		await service.touchFile(FILE, A, { diagnostics: "none", source: "test" });

		expect(texts()).toEqual([`didOpen:${A}`, `didChange:${A}`]);
	});

	// The queue half of the same rule: a record answers what LANDED, and an
	// unknown queue is unknown finality, so it cannot license a skip either.
	it("pushes when a client can report its record but not its queue", async () => {
		const { service, texts } = await setup({ reportQueue: false });

		await service.touchFile(FILE, A, { diagnostics: "none", source: "test" });
		await service.touchFile(FILE, A, { diagnostics: "none", source: "test" });

		expect(texts()).toEqual([`didOpen:${A}`, `didChange:${A}`]);
	});
});

/**
 * #4532 gap 9 F1: the record reports what LANDED. A send of other bytes that
 * the path's queue is still writing lands after a skip, so the server ends on
 * bytes the touch never named — off disk, until the next drift sweep.
 *
 * A real stdio wire cannot be paused, so the transport here is the mock
 * connection (a process boundary) and everything above it is real: the real
 * `LSPService.touchFile`, the real per-document queue, the real notify path.
 * The hold makes "in flight" a fact at the instant the gate reads it, which no
 * socket-based case can promise.
 */
describe("#4532 gap 9 — a skip needs the path's notify queue idle", () => {
	beforeEach(() => {
		getServersForFileWithConfig.mockReset();
		createLSPClient.mockReset();
	});
	afterEach(() => {
		vi.unstubAllEnvs();
		vi.restoreAllMocks();
	});

	it("pushes a touch while a send of other bytes is still in flight", async () => {
		const { service, texts, state } = await setup();
		const touch = { diagnostics: "none" as const, source: "test" };
		await service.touchFile(FILE, A, touch);
		expect(texts()).toEqual([`didOpen:${A}`]);

		// Only B waits at the transport, so its send stays in
		// flight for as long as the case needs it to.
		const held: Array<() => void> = [];
		vi.mocked(state.connection.sendNotification).mockImplementation(
			async (method: string, params: unknown) => {
				if (
					String(method) === "textDocument/didChange" &&
					JSON.stringify(params).includes("const x = 2;")
				) {
					await new Promise<void>((resolve) => {
						held.push(resolve);
					});
				}
				return undefined;
			},
		);
		// The touch that follows waits on the queue behind B; a short write budget
		// keeps that wait bounded (its own verdict is not what this case asserts).
		vi.stubEnv("PI_LENS_LSP_NOTIFY_BUDGET_MS", "50");
		const entry = await service.getClientForFile(FILE);
		expect(
			entry?.client,
			"the case needs the file's live client",
		).toBeDefined();
		const sendingB = entry!.client.notify.open(
			FILE,
			B,
			"typescript",
			undefined,
			true,
		);

		await service.touchFile(FILE, A, touch);

		for (const resolve of held.splice(0)) resolve();
		await sendingB;
		await queueDrained(state);

		// The queue is idle and the server holds the bytes the last touch named.
		expect(texts().at(-1)).toBe(`didChange:${A}`);
		expect(state.documentContentHashes.get(FILE)?.hash).toBe(
			hashDiagnosticContent(A),
		);
		expect(held).toHaveLength(0);
	});

	// R4 P1: a standalone save must preserve the cached content and diagnostics.
	it("skips identical content while a save-only send is slow", async () => {
		const { service, texts, state } = await setup();
		const touch = { diagnostics: "none" as const, source: "test" };
		await service.touchFile(FILE, A, touch);
		state.pushDiagnostics.set(FILE, []);
		vi.stubEnv("PI_LENS_LSP_NOTIFY_BUDGET_MS", "50");
		let release!: () => void;
		const gate = new Promise<void>((resolve) => {
			release = resolve;
		});
		vi.mocked(state.connection.sendNotification).mockImplementation(
			async (method: string) => {
				if (method === "textDocument/didSave") await gate;
			},
		);
		try {
			await service.touchFile(FILE, A, { ...touch, saved: true });
			await waitFor(
				() =>
					vi
						.mocked(state.connection.sendNotification)
						.mock.calls.some(([method]) => method === "textDocument/didSave"),
				(sent) => sent,
				{ timeoutMs: 2_000, yieldControl: tick },
			);
			await service.touchFile(FILE, A, touch);
		} finally {
			release();
			await queueDrained(state);
		}
		expect(texts()).toEqual([`didOpen:${A}`]);
		expect(state.pushDiagnostics.has(FILE)).toBe(true);
	});

	// R4: the kind belongs to the run an entry RETAINS, not to the caller that
	// arrived last. A save coalesced onto a content entry still carries that
	// entry's content (the server ends on those bytes); a content entry
	// coalesced onto a save carries content too. Only a run that sends the save
	// alone leaves the landed record final.
	const pendingWork = async (
		order: "save" | "content-save" | "save-content",
	) => {
		const { service, state, texts } = await setup();
		const touch = { diagnostics: "none" as const, source: "test" };
		await service.touchFile(FILE, A, touch);
		const sends: Promise<boolean>[] = [];
		for (const kind of order.split("-")) {
			sends.push(
				kind === "save"
					? clientModule.handleNotifySave(state, FILE)
					: clientModule.handleNotifyOpen(
							state,
							FILE,
							B,
							"typescript",
							undefined,
							true,
						),
			);
		}
		// Read before the runner starts, which is the state the gate reads a
		// pending entry in.
		const contentBearing = clientModule.hasNotifyInFlightFor(state, FILE);
		await service.touchFile(FILE, A, touch);
		await Promise.all(sends);
		await queueDrained(state);
		return {
			contentBearing,
			hash: state.documentContentHashes.get(FILE)?.hash,
			last: texts().at(-1),
		};
	};

	it("reports a pending save as not content-bearing", async () => {
		const observed = await pendingWork("save");
		expect(observed.contentBearing).toBe(false);
		expect(observed.hash).toBe(hashDiagnosticContent(A));
		expect(observed.last).toBe(`didOpen:${A}`);
	});

	it("reports a save merged onto content as content-bearing", async () => {
		const observed = await pendingWork("content-save");
		expect(observed.contentBearing).toBe(true);
		expect(observed.hash).toBe(hashDiagnosticContent(A));
		expect(observed.last).toBe(`didChange:${A}`);
	});

	it("reports content merged onto a save as content-bearing", async () => {
		const observed = await pendingWork("save-content");
		expect(observed.contentBearing).toBe(true);
		expect(observed.hash).toBe(hashDiagnosticContent(A));
		expect(observed.last).toBe(`didChange:${A}`);
	});

	// R4 P3: overflow removes oldest evidence; re-pushing refreshes its order.
	it("bounds touch evidence at 800 and evicts the oldest unrefreshed entry", async () => {
		const { service, texts } = await setup();
		const touch = { diagnostics: "none" as const, source: "test" };
		const file = (n: number) => `/repo/cap-${n}.ts`;
		for (let n = 0; n < 800; n++) await service.touchFile(file(n), A, touch);
		const count = texts().length;
		await service.touchFile(file(0), A, touch);
		await service.touchFile(file(799), A, touch);
		expect(texts()).toHaveLength(count);
		// A changed push refreshes 0 without changing the population.
		await service.touchFile(file(0), B, touch);
		await service.touchFile(file(800), A, touch);
		const overflow = texts().length;
		await service.touchFile(file(0), B, touch);
		await service.touchFile(file(2), A, touch);
		expect(texts()).toHaveLength(overflow);
		await service.touchFile(file(1), A, touch);
		expect(texts()).toHaveLength(overflow + 1);
	});
});

tests/clients/lsp/workspace-diagnostics-:
/**
 * #608: a full-workspace sweep (`runWorkspaceDiagnostics`) over files that
 * aren't already open in the client's document set used to defeat #271's
 * `WatchedFilesQueue` debounce batching. `WatchedFilesQueue.enqueue` only arms
 * its flush timer on the FIRST call and just accumulates on every call after
 * that until the 100ms debounce window elapses (see watch-queue.ts) — a
 * mechanism built so a burst of file-opens coalesces into ONE project-wide
 * recheck notification instead of N.
 *
 * The sweep's per-file loop processes files SERIALLY, waiting up to several
 * seconds for each file's own diagnostics before moving to the next one. The
 * gap between consecutive first-opens during a sweep is always far longer
 * than the 100ms window, so the debounce never actually coalesced anything —
 * every previously-unopened file fired its own individual watched-files
 * notification, each independently triggering a project-wide recheck on a
 * single-threaded push-diagnostics server (classic tsserver). Later files
 * then timed out purely from queueing behind those rechecks.
 *
 * The fix pre-opens every swept file's document (in one fast, un-gated pass,
 * per server group) BEFORE the diagnostics-wait loop starts, so all the
 * watched-files enqueue calls land inside the SAME 100ms debounce window and
 * coalesce into one flush — restoring #271's "once per burst" intent for a
 * full sweep, not just per-edit dispatch bursts.
 *
 * #621 follow-up: the pre-open pass is now CHUNKED (default width 8, see
 * `WORKSPACE_SWEEP_PREOPEN_CHUNK_SIZE` and
 * workspace-diagnostics-sweep-preopen-chunk.test.ts) instead of firing the
 * WHOLE group's opens in one uninterrupted burst — a whole-group burst at
 * real project scale (~150 files) was found to overwhelm a single-threaded
 * server's request queue before any per-file diagnostics request got a turn.
 * This test's 12 files span 2 chunks (8+4), so it now expects 2 flushes
 * (one per chunk) instead of 1 (one for the whole group) — still far short of
 * 12 (one per file, the original #608 bug this test guards against).
 *
 * This test fakes the client's `notify.open` to reproduce the real
 * `WatchedFilesQueue` coalescing behavior (imported from source, not
 * reimplemented) plus a deliberately SLOW `waitForDiagnostics` (150ms, well
 * past the 100ms debounce) standing in for tsserver's real per-file
 * recompute latency — the exact condition that used to spread first-opens
 * past the debounce window one file at a time. If the pre-open batching
 * regressed back to "open lazily inside the per-file touch", this slow wait
 * would cause N flushes instead of one-per-chunk.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { hashDiagnosticContent } from "../../../clients/lsp/diagnostic-binding.js";
import { WatchedFilesQueue } from "../../../clients/lsp/watch-queue.js";
import { removeTempDirSync } from "../test-utils.js";

const getServersForFileWithConfig = vi.fn();
const createLSPClient = vi.fn();
vi.mock("../../../clients/lsp/config.js", () => ({
	getServersForFileWithConfig,
	getServerInitOverride: vi.fn().mockReturnValue(undefined),
}));
vi.mock("../../../clients/lsp/client.js", () => ({ createLSPClient }));

function makeServer(id: string, ext: string) {
	return {
		id,
		name: id,
		extensions: [ext],
		idleEviction: "resident",
		root: async () => "C:/repo",
		spawn: vi.fn(async () => ({ process: {}, source: "test" })),
	};
}

describe("runWorkspaceDiagnostics — batch-open restores #271 coalescing for a full sweep (#608)", () => {
	let tmp: string;

	beforeEach(() => {
		vi.resetModules();
		getServersForFileWithConfig.mockReset();
		createLSPClient.mockReset();
		tmp = fs.mkdtempSync(path.join(os.tmpdir(), "pi-lens-wsd-batchopen-"));
		// The open count below depends on whether f0's per-file touch lands inside
		// the touch debounce window of the warm-up's push; a window wider than
		// the test makes that deterministic on a loaded runner. Read at import,
		// after the resetModules above.
		vi.stubEnv("PI_LENS_LSP_TOUCH_DEBOUNCE_MS", "600000");
	});

	afterEach(() => {
		vi.unstubAllEnvs();
		removeTempDirSync(tmp);
	});

	it("fires the watched-files notification once for a sweep over N previously-unopened files, not once per file", async () => {
		const fileNames = Array.from({ length: 12 }, (_, i) => `f${i}.ts`);
		for (const n of fileNames) fs.writeFileSync(path.join(tmp, n), "x\n");

		const tsServer = makeServer("typescript", ".ts");
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".ts") ? [tsServer] : [],
		);

		let flushCount = 0;
		let notifiedUriCount = 0;
		const openDocuments = new Set<string>();
		// The real coalescing primitive (#271) — not reimplemented, imported
		// from source — so this test exercises its actual debounce semantics.
		const watchQueue = new WatchedFilesQueue((changes) => {
			flushCount += 1;
			notifiedUriCount += changes.length;
		});

		// #4532 gap 9: the double answers the touch gate the way a real client
		// does, with the record of the payloads its own `notify.open` took, and
		// holds no queue of its own, so nothing is ever in flight. Without the
		// record the gate fails closed and every touch pushes, which is not the
		// coalescing seam this case pins.
		const sent = new Map<string, { hash: string }>();
		const client = {
			isAlive: () => true,
			shutdown: async () => {},
			getWorkspaceDiagnosticsSupport: () => ({
				advertised: false,
				mode: "push-only" as const,
				diagnosticProviderKind: "none",
			}),
			getOperationSupport: () => ({}),
			serverId: "typescript",
			getSentContent: (filePath: string) => sent.get(filePath),
			hasNotifyInFlight: () => false,
			notify: {
				announceCreated: () => undefined,
				// Mirrors `handleNotifyOpen`'s real branch structure closely enough
				// to reproduce the bug/fix: first open of a path enqueues a
				// watched-files change; a later call for an already-open path is
				// just a didChange (no further enqueue).
				open: vi.fn(async (filePath: string, content: string) => {
					sent.set(filePath, { hash: hashDiagnosticContent(content) });
					if (openDocuments.has(filePath)) return;
					openDocuments.add(filePath);
					watchQueue.enqueue(`file://${filePath}`, 2);
				}),
			},
			// Deliberately slower than the 100ms debounce window — stands in for
			// tsserver's real per-file diagnostics latency. Without pre-opening
			// up front, serially awaiting this between each file's `notify.open`
			// would let the debounce timer fire and flush after every single
			// file, reproducing the pre-#608 bug.
			waitForDiagnostics: vi.fn(
				() => new Promise((resolve) => setTimeout(resolve, 150)),
			),
			getDiagnostics: vi.fn(() => []),
		};

		createLSPClient.mockResolvedValue(client);

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const results = await new LSPService().runWorkspaceDiagnostics(tmp);

		expect(results.length).toBe(fileNames.length);
		// Each file's document is opened once in the #608 pre-open pass (the
		// call that actually enqueues a watched-files change) and touched a
		// second time by the main per-file loop's own `touchFile` — which by
		// then finds the document already open and only sends the
		// already-open didChange equivalent (no further enqueue, mirrored by
		// this mock's early return). The #667 pre-sweep warm-up touch runs
		// against the group's first file (f0.ts) BEFORE the #608 pre-open pass
		// even starts — the warm-up call is the one that actually opens f0.ts
		// first; the pre-open pass then finds it already open. The per-file
		// touch of f0.ts then pushes nothing: the warm-up pushed the same bytes
		// to the same server inside the debounce window (#3405 r2: the debounce
		// key no longer carries the client scope, so the warm-up's "primary"
		// push covers the sweep's "all" touch). One warm-up per GROUP (one
		// server here), not one per file.
		expect(client.notify.open).toHaveBeenCalledTimes(fileNames.length * 2);
		// The watched-files queue coalesces each CHUNK's first-opens into its
		// own single flush — 12 files at the default chunk width of 8 is 2
		// chunks (8+4), so 2 flushes from the #608 pre-open pass itself. The
		// #667 warm-up touch above runs BEFORE that pass and pays its own
		// (slow, 150ms) `waitForDiagnostics` wait standing alone against just
		// f0.ts — well past the 100ms debounce window on its own, so it closes
		// out its own flush before the pre-open pass's first chunk even starts
		// enqueuing. That predicts 3 flushes total (2 chunks + 1 warm-up),
		// still nowhere near one flush per file (12) — the #608 regression
		// this test guards against.
		//
		// The EXACT count is not pinned, though: `preOpenGroupFiles` (product
		// code) does a real `await nodeFs.promises.readFile` per file ahead of
		// each `notify.open`, racing the real 100ms debounce timer. Under
		// scheduler contention (full test-suite parallelism) that real I/O can
		// occasionally spread a single chunk's opens fractionally past the
		// window (one extra flush) — legitimate scheduling variance, not a
		// product bug (#902). So assert the invariant this test actually
		// guards — coalescing happened (not one flush for the whole sweep,
		// and nowhere near one per file) — with headroom for that jitter,
		// rather than the single exact number.
		expect(flushCount).toBeGreaterThan(1);
		expect(flushCount).toBeLessThanOrEqual(5); // 3 expected + jitter headroom
		expect(flushCount).toBeLessThan(fileNames.length); // never one-per-file (#608)
		expect(notifiedUriCount).toBe(fileNames.length); // no lost/duplicated URIs
	}, 10_000);
});

/**
 * #615: `preOpenGroupFiles` (the #608 fix above) had NO bound at all — unlike
 * every other per-file step in the sweep (`processFile`'s `touchFile` call is
 * `withDeadline`-wrapped). A real dogfooding incident hung an entire sweep
 * with no heartbeat, no progress, and no escape (pressing Escape didn't even
 * help, since the per-iteration `signal?.aborted` check never gets a turn
 * while stuck inside one file's await). Two bounds were added: a time-based
 * `withDeadline`, and a race against the abort signal so an explicit Escape
 * unblocks immediately rather than waiting out the rest of the per-file
 * budget.
 */
describe("runWorkspaceDiagnostics — pre-open is bounded, not just fast (#615)", () => {
	let tmp: string;
	const ORIGINAL_PER_FILE_MS = process.env.PI_LENS_LSP_WORKSPACE_PER_FILE_MS;
	const ORIGINAL_NOTIFY_BUDGET_MS = process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS;
	const ORIGINAL_WARMUP_RETRY_BACKOFF_MS =
		process.env.PI_LENS_LSP_WARMUP_RETRY_BACKOFF_MS;

	beforeEach(() => {
		vi.resetModules();
		getServersForFileWithConfig.mockReset();
		createLSPClient.mockReset();
		tmp = fs.mkdtempSync(path.join(os.tmpdir(), "pi-lens-wsd-preopen-bound-"));
		// These tests' fake client's notify.open never resolves, so the #667
		// pre-sweep warm-up touch pays the full notify-write budget on both its
		// initial attempt and its retry, plus the backoff between them — flatten
		// both to near-zero so that dead time doesn't dominate the run. The
		// perFileMs bound actually under test is untouched: preOpenGroupFiles
		// bounds notify.open only via withDeadline(perFileMs) (index.ts:3610).
		process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS = "50";
		process.env.PI_LENS_LSP_WARMUP_RETRY_BACKOFF_MS = "0";
	});

	afterEach(() => {
		removeTempDirSync(tmp);
		if (ORIGINAL_PER_FILE_MS === undefined) {
			delete process.env.PI_LENS_LSP_WORKSPACE_PER_FILE_MS;
		} else {
			process.env.PI_LENS_LSP_WORKSPACE_PER_FILE_MS = ORIGINAL_PER_FILE_MS;
		}
		if (ORIGINAL_NOTIFY_BUDGET_MS === undefined) {
			delete process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS;
		} else {
			process.env.PI_LENS_LSP_NOTIFY_BUDGET_MS = ORIGINAL_NOTIFY_BUDGET_MS;
		}
		if (ORIGINAL_WARMUP_RETRY_BACKOFF_MS === undefined) {
			delete process.env.PI_LENS_LSP_WARMUP_RETRY_BACKOFF_MS;
		} else {
			process.env.PI_LENS_LSP_WARMUP_RETRY_BACKOFF_MS =
				ORIGINAL_WARMUP_RETRY_BACKOFF_MS;
		}
	});

	it("a pre-open call that never resolves does not hang the whole sweep — the per-file deadline unblocks it", async () => {
		process.env.PI_LENS_LSP_WORKSPACE_PER_FILE_MS = "150";
		fs.writeFileSync(path.join(tmp, "a.ts"), "x\n");

		const tsServer = makeServer("typescript", ".ts");
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".ts") ? [tsServer] : [],
		);

		const client = {
			isAlive: () => true,
			shutdown: async () => {},
			getWorkspaceDiagnosticsSupport: () => ({
				advertised: false,
				mode: "push-only" as const,
				diagnosticProviderKind: "none",
			}),
			getOperationSupport: () => ({}),
			serverId: "typescript",
			notify: {
				announceCreated: () => undefined,
				// Deliberately never resolves — reproduces a stuck notification
				// write / hung server. Before #615 this hung `preOpenGroupFiles`
				// forever, with no heartbeat and no way for the sweep to move on.
				open: vi.fn(() => new Promise<void>(() => {})),
			},
			waitForDiagnostics: vi.fn(async () => []),
			getDiagnostics: vi.fn(() => []),
		};
		createLSPClient.mockResolvedValue(client);

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const start = Date.now();
		const results = await new LSPService().runWorkspaceDiagnostics(tmp);
		const elapsedMs = Date.now() - start;

		expect(results.length).toBe(1);
		// Should resolve close to the 150ms per-file deadline, not hang forever
		// (or for anywhere near the default 15s budget). With the warm-up dead
		// time flattened above, 1s still leaves ample margin over the deadline.
		expect(elapsedMs).toBeLessThan(1_000);
	}, 10_000);

	it("aborting mid-pre-open unblocks immediately, without waiting out the full per-file deadline", async () => {
		process.env.PI_LENS_LSP_WORKSPACE_PER_FILE_MS = "5000";
		fs.writeFileSync(path.join(tmp, "a.ts"), "x\n");

		const tsServer = makeServer("typescript", ".ts");
		getServersForFileWithConfig.mockImplementation((fp: string) =>
			fp.endsWith(".ts") ? [tsServer] : [],
		);

		const client = {
			isAlive: () => true,
			shutdown: async () => {},
			getWorkspaceDiagnosticsSupport: () => ({
				advertised: false,
				mode: "push-only" as const,
				diagnosticProviderKind: "none",
			}),
			getOperationSupport: () => ({}),
			serverId: "typescript",
			notify: {
				announceCreated: () => undefined,
				open: vi.fn(() => new Promise<void>(() => {})),
			},
			waitForDiagnostics: vi.fn(async () => []),
			getDiagnostics: vi.fn(() => []),
		};
		createLSPClient.mockResolvedValue(client);

		const { LSPService } = await import("../../../clients/lsp/index.js");
		const controller = new AbortController();
		setTimeout(() => controller.abort(), 50);

		const start = Date.now();
		await new LSPService().runWorkspaceDiagnostics(tmp, {
			signal: controller.signal,
		});
		const elapsedMs = Date.now() - start;

		// Aborted at ~50ms; must return well before the 5000ms per-file deadline
		// would have — proving the abort signal itself unblocks the stuck
		// pre-open, not just the timeout.
		expect(elapsedMs).toBeLessThan(2_000);
	}, 10_000);
});

tests/clients/single-flight-ratchet.test:
import { describe, expect, it } from "vitest";

import {
	classifyInFlightSpellings,
	findInFlightDeclarations,
	scanInFlightDeclarations,
	scanInFlightSpellings,
} from "../../tests/support/single-flight-scan.js";

/**
 * Every hand-rolled in-flight declaration `clients/` still carries, and why.
 *
 * `clients/single-flight.ts` (#1753) owns the share, the clear-in-finally, the
 * successor check, and the trailing-rerun bit. Two sites are converted; these
 * are not. A NEW entry has to be added here on purpose, with a reason someone
 * reads — which is the whole ratchet. "Not migrated yet" is an acceptable
 * reason; silence is not.
 *
 * Keys are `clients/`-relative-path:symbol.
 */
const EXEMPTIONS: Record<string, string> = {
	// ── The `ensureInFlight` availability family: #1753's migration backlog ──
	// Identical shape to the two converted sites (biome-client, sg-runner):
	// a latch short-circuit, then at-most-one probe/auto-install. #1753 converts
	// two as proof and burns the rest down opportunistically.
	"dead-code-client.ts:ensureInFlight":
		"backlog: ensureAvailable family, #1753",
	"dependency-checker.ts:ensureInFlight":
		"backlog: ensureAvailable family, #1753",
	"knip-client.ts:ensureInFlight": "backlog: ensureAvailable family, #1753",
	"installer/index.ts:ensureInFlight":
		"backlog: ensureTool's per-tool install map, #1753",

	// ── Per-key result-sharing maps: same primitive, different payload ──
	"dead-code-client.ts:inFlight": "backlog: per-cwd analyze dedupe, #1753",
	"dependency-checker.ts:checkInFlight": "backlog: per-key check dedupe, #1753",
	"dependency-checker.ts:scanInFlight": "backlog: per-root scan dedupe, #1753",
	"knip-client.ts:inFlight": "backlog: per-cwd analyze dedupe, #1753",
	"security-scan-client.ts:inFlight": "backlog: per-cwd scan dedupe, #1753",
	"jscpd-client.ts:inFlight": "backlog: per-cwd analyze dedupe, #1753",
	"dispatch/runners/helm-lint.ts:inFlightByChartRoot":
		"backlog: per-chart-root dedupe, #1753",
	"dispatch/runners/helm-render.ts:inFlightByChartRoot":
		"backlog: per-chart-root dedupe, #1753",
	"dispatch/runners/utils/lazy-installer.ts:inFlight":
		"backlog: per-tool install dedupe, #1753",
	"dispatch/runners/utils/runner-helpers.ts:managedVerifyInFlight":
		"backlog: #1674's generation-guarded verify map, #1753",
	"dispatch/runners/utils/runner-helpers.ts:resolveInstallInFlightByCwd":
		"backlog: #1674's per-cwd install map, #1753",
	"dispatch/runners/utils/runner-helpers.ts:sgAvailableInFlight":
		"backlog: ast-grep availability dedupe, #1753",
	"lsp/config.ts:configInFlight": "backlog: per-workspace config load, #1753",
	"lsp/jvm-runtime.ts:inFlightJavaProbe": "backlog: single JVM probe, #1753",
	"mcp/session.ts:inFlightIpcTurnEnds":
		"backlog: per-cwd Stop-hook pass (#1274), #1753",
	"installer/index.ts:_probeCacheWriteInFlight":
		"backlog: single probe-cache flush, #1753",
	// Skip, not share: a second pre-edit capture of a file while one runs
	// returns `in-flight` instead of joining it, so a write never waits out the
	// remaining bound of a capture the tool_call already abandoned.
	"dispatch/integration.ts:preEditCapturesInFlight":
		"skip-not-join by design: a joined capture would make a write wait on an abandoned one, #4483",
	// Found by review round 1's widened regex: an interface member, which the
	// modifier-only version of this scan never saw. ClientRegistry's
	// `ensureClientForServer` (moved out of lsp/index.ts by #2372 slice 3) is
	// the primitive's shape line for line, identity-checked clear included —
	// the highest-value migration left on this list.
	"lsp/client-registry.ts:inFlight":
		"backlog: LSP spawn dedupe keyed serverId:root, with an " +
		"identity-checked clear in ensureClientForServer's finally — " +
		"hand-rolled singleFlight, #1753",
	"lsp/index.ts:inFlight":
		"alias: LSPState.inFlight holds ClientRegistry's own inFlight Map " +
		"(#2372 slice 3) for the service's readers; the owner is " +
		"lsp/client-registry.ts:inFlight, backlog #1753",

	// ── Not the primitive's shape: these hold no promise per key ──
	"ndjson-logger.ts:inFlightBatch":
		"exempt: the BATCH of queue items one writer is currently flushing, not " +
		"a per-key promise registry — there is one writer per file and nothing " +
		"joins it",
	"project-report.ts:inFlightGraphBuilds":
		"exempt: a Set<string> re-entry guard, not a shared promise per key — " +
		"nothing joins a running build, the second caller simply skips",
	"runtime-coordinator.ts:_startupScansInFlight":
		"exempt: a Map<string, number> COUNTER of outstanding scans, not a " +
		"promise registry — it answers how many, never which promise to join",
	"runtime-tool-result.ts:inFlightPipelines":
		"exempt: a nested map of pipeline RECORDS (state a turn reads and " +
		"mutates), not a dedupe of concurrent callers onto one promise",

	// Landed with #1746 while this branch was open, which is what retired its
	// forward declaration. A single slot rather than a keyed map, and its clear
	// is unconditional ON PURPOSE: #1746's own review round proved an identity
	// check there unreachable, because the slot has one writer and every other
	// caller returns early while it is non-null. Migrating it would hand it a
	// check it does not need, so it is backlog on the merits of dedupe, not of
	// correctness.
	"installer/managed-tool-refresh.ts:refreshInFlight":
		"backlog: #1730's managed-tool refresh latch — a single slot with a " +
		"deliberately unconditional clear, migrate opportunistically, #1753",
};

/**
 * Exemptions written for declarations that are not on this branch YET.
 *
 * Normally an exemption naming a declaration that does not exist is a lie the
 * next reader would trust, and the stale check fails it. This set is the one
 * narrow exception, for a symbol an open PR declares and this branch cannot see
 * yet. Writing the entry ahead of time means neither PR has to be held for the
 * other, and neither author has to notice the interaction.
 *
 * The cost is real and bounded. Two failure modes, handled differently:
 *
 * - The declaration LANDS and the entry parks here forever. The retirement test
 *   below fails that, so the entry has to move into `EXEMPTIONS` where the
 *   normal stale check governs it again. Review round 2 proved this is needed:
 *   creating the declaration locally left all tests green, so nothing but
 *   convention was moving the entry.
 * - The declaration NEVER lands, because its PR is abandoned. Nothing mechanical
 *   catches that, since "not yet" and "never" look identical from here. The size
 *   bound keeps the blast radius to a couple of keys, and a person reading this
 *   comment is the backstop.
 *
 * Empty in steady state, and empty right now. Its one entry so far,
 * `installer/managed-tool-refresh.ts:refreshInFlight`, landed with #1746 while
 * this branch was open. The retirement test below caught it on the first real
 * occasion, and it now sits in `EXEMPTIONS` under the ordinary stale check.
 */
const FORWARD_DECLARED = new Set<string>([]);

describe("singleFlight ratchet (#1753)", () => {
	it("flags every hand-rolled in-flight declaration outside the primitive", () => {
		const unexplained = scanInFlightDeclarations().filter(
			(d) => !EXEMPTIONS[d.key],
		);
		expect(
			unexplained.map((d) => `${d.file}:${d.line} ${d.symbol}`),
			"New at-most-one-in-flight state must use createSingleFlight() from " +
				"clients/single-flight.ts (#1753). If it genuinely is not that shape, " +
				"add it to EXEMPTIONS in this file with a reason that says why.",
		).toEqual([]);
	});

	it("classifies every inFlight spelling in clients/ (#4429)", () => {
		// Recurrence: #4411 review F3, a population scanner that skipped five
		// spellings it did not recognise and passed. Every needle hit must land
		// in a role (single-flight-scan.ts); an unknown position reds here.
		expect(scanInFlightSpellings().unclassified).toEqual([]);
	});

	it("has no stale exemptions", () => {
		// A site that gets migrated (or deleted) must take its entry with it.
		// Otherwise the list rots into a lie, and the next reader trusts it.
		const live = new Set(scanInFlightDeclarations().map((d) => d.key));
		const stale = Object.keys(EXEMPTIONS).filter(
			(key) => !live.has(key) && !FORWARD_DECLARED.has(key),
		);
		expect(stale, "these exemptions no longer match any declaration").toEqual(
			[],
		);
	});

	it("retires a forward declaration once its declaration lands", () => {
		const live = new Set(scanInFlightDeclarations().map((d) => d.key));
		const landed = [...FORWARD_DECLARED].filter((key) => live.has(key));
		expect(landed, "move these out of FORWARD_DECLARED").toEqual([]);
	});

	it("keeps the forward-declaration set small", () => {
		// A forward declaration is a merge-window device: it exists only while a
		// PR that declares the symbol is open alongside this one. More than a
		// couple at once means the set is being used as a general escape hatch
		// from the stale check, which is the one thing it must not become.
		expect(FORWARD_DECLARED.size).toBeLessThanOrEqual(2);
	});

	it("keeps every forward declaration listed in EXEMPTIONS", () => {
		// A forward declaration only suppresses the stale check. It must still
		// carry a reason like any other entry, or it would be a bare hole.
		const orphans = [...FORWARD_DECLARED].filter((key) => !EXEMPTIONS[key]);
		expect(orphans).toEqual([]);
	});

	it("gives every exemption a reason", () => {
		const thin = Object.entries(EXEMPTIONS).filter(
			([, reason]) => reason.trim().length < 20,
		);
		expect(thin.map(([key]) => key)).toEqual([]);
	});

	it("does not exempt the two converted sites", () => {
		// biome-client and sg-runner are the #1753 proof migrations. If either
		// reappears here, the conversion was reverted and this list would quietly
		// bless it.
		const converted = Object.keys(EXEMPTIONS).filter(
			(key) =>
				key.startsWith("biome-client.ts:") || key.startsWith("sg-runner.ts:"),
		);
		expect(converted).toEqual([]);
	});
});

describe("singleFlight ratchet — the scan itself", () => {
	it("catches a hand-rolled class field", () => {
		const found = findInFlightDeclarations(
			"fake-client.ts",
			[
				"export class FakeClient {",
				"\tprivate ensureInFlight: Promise<boolean> | null = null;",
				"}",
			].join("\n"),
		);
		expect(found.map((d) => d.symbol)).toEqual(["ensureInFlight"]);
		expect(found[0].key).toBe("fake-client.ts:ensureInFlight");
		expect(found[0].line).toBe(2);
	});

	it("catches a hand-rolled module-level map", () => {
		const found = findInFlightDeclarations(
			"fake.ts",
			"const inFlightByCwd = new Map<string, Promise<void>>();\n",
		);
		expect(found.map((d) => d.symbol)).toEqual(["inFlightByCwd"]);
	});

	it("does not fire on a comment or a string that merely names one", () => {
		// The false-positive mode `session-state-scan.ts` documents: a doc
		// comment naming a field must not read as a declaration of it.
		const found = findInFlightDeclarations(
			"fake.ts",
			[
				"/** const ensureInFlight: Promise<boolean> | null = null; */",
				'const label = "const ensureInFlight = null;";',
			].join("\n"),
		);
		expect(found).toEqual([]);
	});

	it("catches a modifier-less class field that carries a type annotation", () => {
		// Review round 1's finding: the migrated sites' exact field minus the
		// word `private`. A modifier-only regex sails past it.
		const found = findInFlightDeclarations(
			"fake-client.ts",
			[
				"export class FakeClient {",
				"\tprobeInFlight: Promise<void> | null = null;",
				"}",
			].join("\n"),
		);
		expect(found.map((d) => d.symbol)).toEqual(["probeInFlight"]);
	});

	it("catches an optional modifier-less field", () => {
		const found = findInFlightDeclarations(
			"fake.ts",
			"interface State {\n\tinFlight?: Map<string, Promise<void>>;\n}\n",
		);
		expect(found.map((d) => d.symbol)).toEqual(["inFlight"]);
	});

	it("catches a #private class field", () => {
		const found = findInFlightDeclarations(
			"fake-client.ts",
			"class C {\n\t#ensureInFlight = new Map<string, Promise<void>>();\n}\n",
		);
		expect(found.map((d) => d.symbol)).toEqual(["ensureInFlight"]);
	});

	it.each([
		[
			"an override field",
			"class C {\n\toverride inFlight: Promise<void> | null = null;\n}\n",
		],
		[
			"a declare field",
			"class C {\n\tdeclare inFlight: Map<string, Promise<void>>;\n}\n",
		],
		[
			"an accessor field",
			"class C {\n\taccessor inFlight = new Map<string, Promise<void>>();\n}\n",
		],
		[
			"an unannotated modifier-less field",
			"class C {\n\tinFlight = new Map<string, Promise<void>>();\n}\n",
		],
		["a one-line class", "class C { private inFlight = new Map(); }\n"],
		[
			"a second declarator",
			"let ready = false, inFlight = new Map<string, Promise<void>>();\n",
		],
		["a module-level destructuring", "const { inFlight } = makeState();\n"],
		[
			"a multi-line constructor parameter property",
			"class C {\n\tconstructor(\n\t\tprivate readonly inFlight = new Map<string, Promise<void>>(),\n\t) {}\n}\n",
		],
		[
			"a one-line constructor parameter property",
			"class C { constructor(private inFlight: Map<string, Promise<void>>) {} }\n",
		],
		[
			"an override parameter property",
			"class C extends B { constructor(override inFlight?: Promise<void>) { super(); } }\n",
		],
	])(
		"counts a declaration the regex scan missed: %s (#4429)",
		(_name, source) => {
			// Shape 34: the regex enumerated three line-leading spellings; the AST
			// reads the grammar position, so each of these is the same declaration.
			expect(
				findInFlightDeclarations("fake.ts", source).map((d) => d.symbol),
			).toEqual(["inFlight"]);
		},
	);

	it("reports a spelling it cannot classify, with its file and line (#4429)", () => {
		// The fail-closed branch: an enum member and an import alias are
		// positions the role table does not know, so they red, never skip.
		const scan = classifyInFlightSpellings(
			"fake.ts",
			[
				"const ready = true;",
				"enum Phase { inFlight }",
				'import inFlight = require("./state");',
			].join("\n"),
		);
		expect(scan.declarations).toEqual([]);
		expect(scan.unclassified).toEqual([
			"unclassified spelling at fake.ts:2: enum Phase { inFlight } (property_identifier under enum_body)",
			'unclassified spelling at fake.ts:3: import inFlight = require("./state"); (identifier under import_require_clause)',
		]);
	});

	it("ignores an unclassifiable spelling inside a comment or a string (#4429)", () => {
		const scan = classifyInFlightSpellings(
			"fake.ts",
			[
				"// enum Phase { inFlight }",
				'/* import inFlight = require("./state"); */',
				'const text = "enum Phase { inFlight }";',
			].join("\n"),
		);
		expect(scan).toEqual({ declarations: [], unclassified: [] });
	});

	it("classifies a method signature as a name, not state (#4532)", () => {
		// `hasNotifyInFlight?(filePath: string): boolean` on `LSPClient` is a
		// question the touch gate asks the queue. Reading it as state would put a
		// method on the burn-down list and hide the real fields beside it.
		const scan = classifyInFlightSpellings(
			"fake.ts",
			[
				"interface Client {",
				"\tgetSentContent?(filePath: string): { hash: string } | undefined;",
				"\thasNotifyInFlight?(filePath: string): boolean;",
				"}",
			].join("\n"),
		);
		expect(scan).toEqual({ declarations: [], unclassified: [] });
	});

	it("classifies parameters and function locals as locals, not state (#4429)", () => {
		// `lsp/client-registry.ts`'s `onSpawnInFlight` parameter was a regex
		// false positive with an exemption; a parameter holds no module state.
		const scan = classifyInFlightSpellings(
			"fake.ts",
			[
				"function f(",
				"\tonSpawnInFlight?: (id: string) => void,",
				") {",
				"\tconst inFlight = new Map();",
				"\ttry {} catch (inFlightError) {}",
				"\tfor (const inFlightItem of inFlight.values()) void inFlightItem;",
				"}",
			].join("\n"),
		);
		expect(scan).toEqual({ declarations: [], unclassified: [] });
	});

	it("does not fire on a bare assignment to an existing field", () => {
		// `this.ensureInFlight = null` is the clear, not a new declaration.
		const found = findInFlightDeclarations(
			"fake.ts",
			"\t\t\tensureInFlight = null;\n",
		);
		expect(found).toEqual([]);
	});
});

tests/config/tla-switch-pins.test.ts:
/**
 * Governance: every TLA+ config constant that mirrors a code choice is pinned
 * to the code's real behaviour (#4393).
 *
 * Recurrence: #4387. #4235 (55fa5210c) removed the read guard's injected
 * whole-file read on the zero-read allow, while `formal/read-guard` kept
 * modelling that read. The coverage rule (#3802) only checks that a PR
 * touching a modelled file mentions the model, so TLC stayed green on the old
 * design and two read-guard defects stayed invisible until an external
 * report. AGENTS.md shape 68 ("Model switch drift") names the class.
 *
 * `formal/switch-pins.json` classifies every constant of every family:
 *
 * - `pins`: the constant mirrors a code choice, and a named test drives the
 *   real code (a dispatcher or the guard's entry point) and asserts the
 *   behaviour of the pinned `value`; `also` names further tests when one
 *   value encodes several behaviours. Flipping the code reds that test;
 *   flipping the model without the registry reds this one. Flipping the
 *   model and the registry together, without the code, reds neither: the
 *   registry ties a constant to a title, not to what the test asserts, so a
 *   value change in the registry is the reviewer's to judge.
 * - `notCodeChoice`: a scenario bound, an actor set, an environment
 *   behaviour, a mutant-only design, or a switch the model reads only under
 *   another switch's old value. Each group carries its reason.
 * - `deferred`: a code choice with no pin yet, with its reason. A family in
 *   `FULLY_PINNED` may defer nothing, and the counts of deferred and
 *   notCodeChoice members are pinned exactly (`DEFERRED_COUNT`,
 *   `NOT_CODE_CHOICE_COUNT`).
 *
 * The population is every name a family's configs assign in a `CONSTANTS`
 * section, `=` or `<-` (the `<-` form covers a module switch such as
 * `ZeroReadInjects <- ZeroReadInjectsPre4387`), and every module
 * `Name == TRUE|FALSE` that no config substitutes as a `<-` target. The as-built configs are the
 * ones whose header says `\* expect: pass` (the existing convention; no
 * family has a separate "current" config). A pin's value must be what every
 * as-built config resolves the constant to: its `=` value, the definition its
 * `<-` names, or else the module's own `Name == <literal>` definition. A
 * value a config uses only to narrow the explored schedules is admitted per
 * pin, per value and per named config, in `narrowedBy`, with its reason; a
 * config the entry does not list must match the pinned value.
 *
 * Detectors match code, not prose (principles §2):
 * - TLA+ text (`.cfg` and `.tla`) is read after `stripTlaComments` blanks
 *   `\*` line comments and nested `(* *)` blocks, so a comment that quotes
 *   `ZeroReadInjects == FALSE` or an old assignment cannot decide a value.
 *   TLA+ string literals are values and stay intact.
 * - A pin's evidence is a test title, which is itself a string literal, so
 *   the per-needle policy is positional and liveness-checked: the title
 *   counts only as the first argument of an `it(...)` / `test(...)` call (or
 *   of the call an `it.each(...)` returns) that a run reaches, in a file
 *   vitest's own config collects (`vitestCollects`). `testDeclarations`
 *   (tests/support/sweep-kit.ts) decides that: a comment is not a call, and
 *   a skipped, todo, conditional (`skipIf`/`runIf`) or `fails` test (by
 *   chain, by options object, or by unread options), a test whose body calls
 *   a skip, a test in such a suite, a dead branch or an uncalled function,
 *   and an `.only` file's siblings are absent. The title is compared as written in
 *   source: escape sequences unexpanded and `${...}` placeholders verbatim.
 *   Not seen: an empty `each` table, an early `return` in a suite, and a
 *   parametrized pin whose pinned row was removed from its table.
 */
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { parseModelHeader } from "../../scripts/check-tla-models.mjs";
import { assertNonEmptyScan, testDeclarations } from "../support/sweep-kit.js";
import { vitestCollects } from "../support/vitest-collection.js";

const REPO_ROOT = path.resolve(import.meta.dirname, "../..");
const REGISTRY_PATH = "formal/switch-pins.json";
/** Families whose every code-choice constant has a pin (#4393 acceptance). */
const FULLY_PINNED = [
	"read-guard",
	"format-drain",
	"dispatch-pipeline",
	"blocker-pending",
	"cascade-delivery",
];
/**
 * The deferred and notCodeChoice members across all families, pinned exactly
 * (#4399 verify r2 F4). A ceiling let a freed slot be reused, and let a member
 * move from `deferred` to `notCodeChoice` while a new code choice took its
 * place. Every change to either count is now a visible edit here: lower
 * `DEFERRED_COUNT` as pins land, and a reviewer judges every rise of either.
 */
const DEFERRED_COUNT = 136;
const NOT_CODE_CHOICE_COUNT = 236;

interface PinTest {
	test: string;
	title: string;
}
interface Pin extends PinTest {
	value: string;
	/** Further tests, when one value encodes several behaviours (a model
	 *  definition such as `SpendLicense == BridgeNoAdvance` reuses it). */
	also?: PinTest[];
	/** Per value, the as-built configs (file stems) that use it only to narrow
	 *  the explored schedules, with the reason. */
	narrowedBy?: Record<string, { configs: string[]; reason: string }>;
}
interface Group {
	reason: string;
	constants: string[];
}
interface FamilyEntry {
	pins?: Record<string, Pin>;
	notCodeChoice?: Group[];
	deferred?: Group[];
}
interface Registry {
	families: Record<string, FamilyEntry>;
}

/**
 * Blank TLA+ comments in place (`\*` to end of line, nested `(* *)`), keeping
 * string literals and newlines. A `\*` or `(*` inside a string is text.
 */
export function stripTlaComments(text: string): string {
	const out = text.split("");
	let depth = 0;
	let inString = false;
	let lineComment = false;
	for (let i = 0; i < text.length; i++) {
		const ch = text[i];
		const next = text[i + 1];
		if (lineComment) {
			if (ch === "\n") lineComment = false;
			else out[i] = " ";
			continue;
		}
		if (depth > 0) {
			if (ch === "(" && next === "*") {
				depth++;
				out[i] = " ";
				out[i + 1] = " ";
				i++;
			} else if (ch === "*" && next === ")") {
				depth--;
				out[i] = " ";
				out[i + 1] = " ";
				i++;
			} else if (ch !== "\n") out[i] = " ";
			continue;
		}
		if (inString) {
			if (ch === "\\") i++;
			else if (ch === '"') inString = false;
			continue;
		}
		if (ch === '"') inString = true;
		else if (ch === "\\" && next === "*") {
			lineComment = true;
			out[i] = " ";
			out[i + 1] = " ";
			i++;
		} else if (ch === "(" && next === "*") {
			depth = 1;
			out[i] = " ";
			out[i + 1] = " ";
			i++;
		}
	}
	return out.join("");
}

/** Collapse whitespace outside TLA+ string literals. */
function normalizeValue(value: string): string {
	let out = "";
	let inString = false;
	for (let i = 0; i < value.length; i++) {
		const ch = value[i];
		if (inString) {
			out += ch;
			if (ch === "\\") out += value[++i] ?? "";
			else if (ch === '"') inString = false;
		} else if (ch === '"') {
			inString = true;
			out += ch;
		} else if (!/\s/.test(ch)) out += ch;
	}
	return out;
}

const CFG_KEYWORD =
	/^\s*(CONSTANTS?|SPECIFICATION|INIT|NEXT|INVARIANTS?|PROPERTY|PROPERTIES|CHECK_DEADLOCK|CONSTRAINTS?|ACTION_CONSTRAINTS?|SYMMETRY|VIEW|ALIAS|POSTCONDITION)\b(.*)$/;

export interface CfgAssignment {
	kind: "=" | "<-";
	value: string;
}

/** The `CONSTANTS` assignments of a `.cfg`, read from comment-blanked text. */
export function parseCfgConstants(text: string): Map<string, CfgAssignment> {
	const entries = new Map<string, CfgAssignment>();
	let inConstants = false;
	let current: string | undefined;
	for (const raw of stripTlaComments(text).split("\n")) {
		let line = raw;
		const keyword = CFG_KEYWORD.exec(line);
		if (keyword) {
			inConstants = /^CONSTANTS?$/.test(keyword[1]);
			current = undefined;
			line = keyword[2];
		}
		if (!inConstants || line.trim() === "") continue;
		const start = /^\s*([A-Za-z_]\w*)\s*(=|<-)\s*(.*)$/.exec(line);
		if (start) {
			current = start[1];
			entries.set(current, {
				kind: start[2] as "=" | "<-",
				value: start[3],
			});
		} else if (current !== undefined) {
			const entry = entries.get(current);
			if (entry) entry.value += ` ${line}`;
		}
	}
	for (const entry of entries.values())
		entry.value = normalizeValue(entry.value);
	return entries;
}

/** Top-level one-line `Name == <literal>` definitions of a `.tla` module. */
export function parseLiteralDefinitions(text: string): Map<string, string> {
	const defs = new Map<string, string>();
	for (const match of stripTlaComments(text).matchAll(
		/^([A-Za-z_]\w*)\s*==\s*(TRUE|FALSE|-?\d+|"(?:[^"\\]|\\.)*")\s*$/gm,
	))
		defs.set(match[1], match[2]);
	return defs;
}

/**
 * Titles of the `it`/`test` declarations a run reaches, as written in source
 * (the shared walker, {@link testDeclarations}). A skipped, todo,
 * conditional or `fails` test, one in a skipped suite, a dead branch or an
 * uncalled function, and an `.only` file's siblings are absent.
 */
export function declaredTestTitles(source: string): Set<string> {
	return new Set(
		testDeclarations(source)
			.filter(
				(declaration) =>
					declaration.live &&
					(declaration.callee === "it" || declaration.callee === "test"),
			)
			.map((declaration) => declaration.title),
	);
}

interface FamilyModels {
	/** Every name a config of the family assigns, `=` or `<-`, and every
	 *  module boolean definition that is not a `<-` target. */
	population: Set<string>;
	/** Each `\* expect: pass` config with its module's literal definitions and
	 *  its comment-blanked text (undefined when the module file is absent). */
	asBuilt: Array<{
		file: string;
		constants: Map<string, CfgAssignment>;
		defs: Map<string, string>;
		moduleText: string | undefined;
	}>;
}

function readFamily(root: string, family: string): FamilyModels {
	const dir = path.join(root, "formal", family);
	const population = new Set<string>();
	const asBuilt: FamilyModels["asBuilt"] = [];
	const defsByModule = new Map<string, Map<string, string>>();
	const textByModule = new Map<string, string | undefined>();
	const targets = new Set<string>();
	for (const name of fs.readdirSync(dir).sort()) {
		if (!name.endsWith(".cfg")) continue;
		const text = fs.readFileSync(path.join(dir, name), "utf8");
		const constants = parseCfgConstants(text);
		for (const [constant, assignment] of constants) {
			population.add(constant);
			if (assignment.kind === "<-") targets.add(assignment.value);
		}
		const header = parseModelHeader(text);
		if ("error" in header || header.expect.status !== "pass") continue;
		let defs = defsByModule.get(header.module);
		if (!defs) {
			const tla = path.join(dir, `${header.module}.tla`);
			const moduleText = fs.existsSync(tla)
				? stripTlaComments(fs.readFileSync(tla, "utf8"))
				: undefined;
			defs =
				moduleText === undefined
					? new Map()
					: parseLiteralDefinitions(moduleText);
			defsByModule.set(header.module, defs);
			textByModule.set(header.module, moduleText);
		}
		asBuilt.push({
			file: `formal/${family}/${name}`,
			constants,
			defs,
			moduleText: textByModule.get(header.module),
		});
	}
	// A module's own boolean switch (`Name == TRUE`) that no config assigns is
	// a code choice too (#4399 review F4); a `<-` target such as
	// `ZeroReadInjectsPre4387` is a mutant's value, not a switch.
	for (const name of fs.readdirSync(dir).sort()) {
		if (!name.endsWith(".tla")) continue;
		const defs = parseLiteralDefinitions(
			fs.readFileSync(path.join(dir, name), "utf8"),
		);
		for (const [constant, value] of defs)
			if ((value === "TRUE" || value === "FALSE") && !targets.has(constant))
				population.add(constant);
	}
	return { population, asBuilt };
}

/**
 * The value an as-built config gives `constant`: its `=` value, the literal
 * definition its `<-` names, or the module's own literal definition.
 */
function resolveValue(
	config: FamilyModels["asBuilt"][number],
	constant: string,
): string | undefined {
	const assigned = config.constants.get(constant);
	if (assigned?.kind === "=") return assigned.value;
	return config.defs.get(assigned?.value ?? constant);
}

/** Every disagreement between the registry, the models and the tests. */
export function auditSwitchPins(root: string, registry: Registry): string[] {
	const errors: string[] = [];
	const formal = path.join(root, "formal");
	const familyDirs = fs
		.readdirSync(formal, { withFileTypes: true })
		.filter((entry) => entry.isDirectory())
		.map((entry) => entry.name)
		.sort();
	const listed = Object.keys(registry.families ?? {});
	for (const family of listed)
		if (!familyDirs.includes(family))
			errors.push(
				`${family}: listed in ${REGISTRY_PATH} but no formal/${family}/`,
			);
	const titleCache = new Map<string, Set<string> | undefined>();
	for (const family of familyDirs) {
		const entry = registry.families?.[family];
		if (!entry) {
			errors.push(
				`${family}: formal/${family}/ has no entry in ${REGISTRY_PATH}`,
			);
			continue;
		}
		const models = readFamily(root, family);
		const seen = new Map<string, string>();
		const classify = (constant: string, where: string) => {
			const prior = seen.get(constant);
			if (prior)
				errors.push(
					`${family}.${constant}: classified twice (${prior}, ${where})`,
				);
			seen.set(constant, where);
		};
		for (const constant of Object.keys(entry.pins ?? {}))
			classify(constant, "pins");
		for (const kind of ["notCodeChoice", "deferred"] as const)
			for (const group of entry[kind] ?? []) {
				if (!group.reason?.trim())
					errors.push(`${family}: a ${kind} group has no reason`);
				for (const constant of group.constants ?? []) classify(constant, kind);
			}
		for (const constant of models.population)
			if (!seen.has(constant))
				errors.push(
					`${family}.${constant}: unclassified; pin it, or give a notCodeChoice or deferred reason`,
				);
		for (const constant of seen.keys())
			if (!models.population.has(constant))
				errors.push(
					`${family}.${constant}: stale; no config of the family assigns it`,
				);
		if (FULLY_PINNED.includes(family) && (entry.deferred ?? []).length > 0)
			errors.push(`${family}: fully pinned, so it may defer nothing`);
		for (const [constant, pin] of Object.entries(entry.pins ?? {})) {
			const label = `${family}.${constant}`;
			const narrowedBy = pin.narrowedBy ?? {};
			// value -> the as-built configs (file stems) that resolve to it
			const used = new Map<string, Set<string>>();
			for (const config of models.asBuilt) {
				const value = resolveValue(config, constant);
				if (value === undefined) {
					// A config of another module of the family (SiblingRestore.tla
					// beside DispatchPipeline.tla): a module whose code never names
					// the constant has no value for it, and nothing to compare.
					if (
						config.moduleText !== undefined &&
						!new RegExp(`\\b${constant}\\b`).test(config.moduleText)
					)
						continue;
					errors.push(
						`${label}: ${config.file} gives no literal value to compare`,
					);
					continue;
				}
				const stem = path.basename(config.file, ".cfg");
				used.set(value, (used.get(value) ?? new Set<string>()).add(stem));
				// Per config, not per value: a value admitted for one config must
				// not hide the same value in another (#4393: RestoreGatesHold = TRUE
				// stayed admitted for the headline config by a sibling's narrowing).
				if (value !== pin.value && !narrowedBy[value]?.configs?.includes(stem))
					errors.push(
						`${label}: pinned ${pin.value}, but ${config.file} (expect: pass) has ${value}`,
					);
			}
			if (!used.has(pin.value))
				errors.push(
					`${label}: no as-built config has the pinned value ${pin.value}`,
				);
			for (const [value, entry] of Object.entries(narrowedBy)) {
				if (!entry.reason?.trim())
					errors.push(`${label}: narrowedBy ${value} has no reason`);
				if (value === pin.value)
					errors.push(`${label}: narrowedBy ${value} is the pinned value`);
				if (!entry.configs?.length)
					errors.push(`${label}: narrowedBy ${value} names no config`);
				for (const stem of entry.configs ?? [])
					if (!used.get(value)?.has(stem))
						errors.push(
							`${label}: stale narrowedBy ${value}; ${stem} is no as-built config with that value`,
						);
			}
			for (const { test, title } of [pin, ...(pin.also ?? [])]) {
				if (!vitestCollects(test)) {
					errors.push(
						`${label}: pin test ${test} is not a test file vitest collects`,
					);
					continue;
				}
				if (!titleCache.has(test)) {
					const file = path.join(root, test);
					titleCache.set(
						test,
						fs.existsSync(file)
							? declaredTestTitles(fs.readFileSync(file, "utf8"))
							: undefined,
					);
				}
				const titles = titleCache.get(test);
				if (!titles) errors.push(`${label}: pin test ${test} does not exist`);
				else if (!titles.has(title))
					errors.push(`${label}: ${test} declares no test titled "${title}"`);
			}
		}
	}
	return errors;
}

function loadRegistry(root: string): Registry {
	return JSON.parse(fs.readFileSync(path.join(root, REGISTRY_PATH), "utf8"));
}

describe("TLA+ switch pins (#4393, recurrence #4387)", () => {
	it("pins or classifies every constant of every family, and each pin agrees with its as-built configs", () => {
		const registry = loadRegistry(REPO_ROOT);
		// Floors: a parser that read nothing would report a clean registry.
		const readGuard = readFamily(REPO_ROOT, "read-guard");
		assertNonEmptyScan("read-guard as-built configs", readGuard.asBuilt.length);
		expect(readGuard.population).toContain("ZeroReadInjects");
		expect(readGuard.population).toContain("AuthorIdentity");
		// The value itself is the audit's to judge; the floor only proves the
		// resolver reached a module definition.
		expect(resolveValue(readGuard.asBuilt[0], "ZeroReadInjects")).toMatch(
			/^(TRUE|FALSE)$/,
		);
		assertNonEmptyScan(
			"read-guard pins",
			Object.keys(registry.families["read-guard"]?.pins ?? {}).length,
		);
		expect(auditSwitchPins(REPO_ROOT, registry)).toEqual([]);
		const members = (kind: "deferred" | "notCodeChoice") =>
			Object.values(registry.families).flatMap((entry) =>
				(entry[kind] ?? []).flatMap((group) => group.constants),
			).length;
		expect(members("deferred")).toBe(DEFERRED_COUNT);
		expect(members("notCodeChoice")).toBe(NOT_CODE_CHOICE_COUNT);
	});

	describe("on a fixture tree", () => {
		let root: string | undefined;
		afterEach(() => {
			if (root) fs.rmSync(root, { recursive: true, force: true });
			root = undefined;
		});

		const MODULE = [
			"---- MODULE M ----",
			"CONSTANTS Mode, Size",
			"\\* Inject == FALSE   (a comment quoting the old value)",
			"Inject == TRUE",
			"InjectPre == FALSE",
			"====",
		].join("\n");
		const cfg = (expect: string, body: string) =>
			[
				`\\* expect: ${expect}`,
				"\\* module: M",
				"CONSTANTS",
				body,
				"SPECIFICATION Spec",
				"CHECK_DEADLOCK FALSE",
			].join("\n");
		const TEST = [
			'it("pins the injection", () => {});',
			'it.each([1, 2])("pins mode %s", () => {});',
			'// it("a fake pin", () => {});',
			'const t = "a string pin";',
			'it.skip("a skipped pin", () => {});',
			'describe("a live suite", () => {',
			"\tfor (const n of [1, 2]) {",
			'\t\tit("a loop pin", () => {});',
			"\t}",
			"});",
			'describe.skip("a skipped suite", () => {',
			'\tit("a pin in a skipped suite", () => {});',
			"});",
			'describe.skipIf(true)("a conditional suite", () => {',
			'\tit("a pin in a conditional suite", () => {});',
			"});",
			'if (process.pid < 0) it("a pin in a dead branch", () => {});',
			'const never = () => it("a pin in an uncalled function", () => {});',
			'it.todo("a todo pin");',
			'test.skip("a skipped test pin", () => {});',
			'it("an options-skipped pin", { skip: true }, () => {});',
			'it("an options-todo pin", { todo: true }, () => {});',
			'it("an options-fails pin", { fails: true }, () => {});',
			"const opts = { skip: true };",
			'it("a pin with unread options", opts, () => {});',
			'it("a pin with a timeout option", { timeout: 5, skip: false }, () => {});',
			'it("a pin with a timeout", () => {}, 30_000);',
			'describe("an options-skipped suite", { skip: true }, () => {',
			'\tit("a pin in an options-skipped suite", () => {});',
			"});",
			'it("a pin that skips itself", (ctx) => {',
			"\tctx.skip();",
			"});",
			'it("a pin that skips by its parameter", ({ skip }) => {',
			"\tskip();",
			"});",
		].join("\n");
		/** A file with an `.only`: its siblings never run. */
		const ONLY = [
			'it.only("the only test", () => {});',
			'it("a sibling of an only", () => {});',
		].join("\n");
		/** The same through an options object. */
		const OPTIONS_ONLY = [
			'it("the options-only test", { only: true }, () => {});',
			'it("a sibling of an options only", () => {});',
		].join("\n");
		/** A support module: vitest never collects it, whatever it declares. */
		const SUPPORT = 'it("a support pin", () => {});';

		function tree(cfgs: Record<string, string>) {
			root = fs.mkdtempSync(path.join(os.tmpdir(), "pi-lens-switch-pins-"));
			fs.mkdirSync(path.join(root, "formal", "fam"), { recursive: true });
			fs.mkdirSync(path.join(root, "tests"));
			fs.writeFileSync(path.join(root, "formal", "fam", "M.tla"), MODULE);
			for (const [name, text] of Object.entries({
				"Mutant.cfg": MUTANT,
				...cfgs,
			}))
				fs.writeFileSync(path.join(root, "formal", "fam", name), text);
			fs.writeFileSync(path.join(root, "tests", "p.test.ts"), TEST);
			fs.writeFileSync(path.join(root, "tests", "only.test.ts"), ONLY);
			fs.writeFileSync(path.join(root, "tests", "support.ts"), SUPPORT);
			fs.writeFileSync(
				path.join(root, "tests", "options-only.test.ts"),
				OPTIONS_ONLY,
			);
			// vitest.config.ts excludes tests/fixtures/**, so this never runs.
			fs.mkdirSync(path.join(root, "tests", "fixtures"));
			fs.writeFileSync(
				path.join(root, "tests", "fixtures", "f.test.ts"),
				SUPPORT,
			);
			return root;
		}
		const PASS = cfg("pass", '    Mode = "on"\n    Size = 2');
		const MUTANT = cfg(
			"violated Inv",
			'    Mode = "off"\n    Size = 2\n    Inject <- InjectPre',
		);
		const registry = (pins: Record<string, Pin>, extra: FamilyEntry = {}) => ({
			families: {
				fam: {
					pins,
					notCodeChoice: [{ reason: "a scenario bound", constants: ["Size"] }],
					...extra,
				},
			},
		});
		const GOOD: Record<string, Pin> = {
			Inject: {
				value: "TRUE",
				test: "tests/p.test.ts",
				title: "pins the injection",
			},
			Mode: { value: '"on"', test: "tests/p.test.ts", title: "pins mode %s" },
		};

		it("accepts pins that agree with every as-built config", () => {
			const fixture = tree({ "Pass.cfg": PASS, "Mutant.cfg": MUTANT });
			expect(auditSwitchPins(fixture, registry(GOOD))).toEqual([]);
		});

		it("reds a pin whose value an as-built config contradicts", () => {
			const fixture = tree({
				"Pass.cfg": PASS,
				"Old.cfg": cfg(
					"pass",
					'    Mode = "on"\n    Size = 2\n    Inject <- InjectPre',
				),
			});
			expect(auditSwitchPins(fixture, registry(GOOD))).toEqual([
				"fam.Inject: pinned TRUE, but formal/fam/Old.cfg (expect: pass) has FALSE",
			]);
		});

		it("reds a model flip the registry did not follow", () => {
			const fixture = tree({ "Pass.cfg": PASS });
			fs.writeFileSync(
				path.join(fixture, "formal", "fam", "M.tla"),
				MODULE.replace("Inject == TRUE", "Inject == FALSE"),
			);
			expect(auditSwitchPins(fixture, registry(GOOD))).toEqual([
				"fam.Inject: pinned TRUE, but formal/fam/Pass.cfg (expect: pass) has FALSE",
				"fam.Inject: no as-built config has the pinned value TRUE",
			]);
		});

		it("does not let a comment decide a config value", () => {
			const fixture = tree({
				"Pass.cfg": cfg(
					"pass",
					'    Mode = "off" \\* Mode = "on"\n    (* Mode = "on" *)\n    Size = 2',
				),
			});
			expect(auditSwitchPins(fixture, registry(GOOD))).toEqual([
				'fam.Mode: pinned "on", but formal/fam/Pass.cfg (expect: pass) has "off"',
				'fam.Mode: no as-built config has the pinned value "on"',
			]);
		});

		it("reds a module switch no config assigns, but not a mutant's target", () => {
			// Recurrence: #4399 review F4. A `.tla`-only `Name == TRUE` was
			// outside the population, so a new switch needed no pin.
			const fixture = tree({ "Pass.cfg": PASS });
			fs.writeFileSync(
				path.join(fixture, "formal", "fam", "M.tla"),
				MODULE.replace("====", "NewSwitch == TRUE\n===="),
			);
			expect(auditSwitchPins(fixture, registry(GOOD))).toEqual([
				"fam.NewSwitch: unclassified; pin it, or give a notCodeChoice or deferred reason",
			]);
		});

		it("reds a constant with no classification, and a stale one", () => {
			const fixture = tree({ "Pass.cfg": PASS });
			const { Mode: _mode, ...withoutMode } = GOOD;
			expect(
				auditSwitchPins(
					fixture,
					registry(withoutMode, {
						deferred: [{ reason: "later", constants: ["Gone"] }],
					}),
				),
			).toEqual([
				"fam.Mode: unclassified; pin it, or give a notCodeChoice or deferred reason",
				"fam.Gone: stale; no config of the family assigns it",
			]);
		});

		it("does not let a comment, a stray string or a skipped test name a pin (self-excuse)", () => {
			const fixture = tree({ "Pass.cfg": PASS });
			const pins = (title: string) => ({
				...GOOD,
				Inject: { ...GOOD.Inject, title },
			});
			for (const title of ["a fake pin", "a string pin", "a skipped pin"])
				expect(auditSwitchPins(fixture, registry(pins(title)))).toEqual([
					`fam.Inject: tests/p.test.ts declares no test titled "${title}"`,
				]);
		});

		it("does not let a skipped or conditional suite, a dead branch, an uncalled function, a todo, an only's sibling or a support file name a pin", () => {
			// Recurrence: #4399 review F1. Each form left the gate green on the
			// real tree while vitest never ran the pin (a skipped pin is a
			// deleted pin).
			const fixture = tree({ "Pass.cfg": PASS });
			const pinAt = (test: string, title: string) =>
				registry({ ...GOOD, Inject: { ...GOOD.Inject, test, title } });
			expect(
				auditSwitchPins(fixture, pinAt("tests/p.test.ts", "a loop pin")),
			).toEqual([]);
			for (const title of [
				"a pin in a skipped suite",
				"a pin in a conditional suite",
				"a pin in a dead branch",
				"a pin in an uncalled function",
				"a todo pin",
				"a skipped test pin",
			])
				expect(
					auditSwitchPins(fixture, pinAt("tests/p.test.ts", title)),
				).toEqual([
					`fam.Inject: tests/p.test.ts declares no test titled "${title}"`,
				]);
			expect(
				auditSwitchPins(
					fixture,
					pinAt("tests/only.test.ts", "a sibling of an only"),
				),
			).toEqual([
				'fam.Inject: tests/only.test.ts declares no test titled "a sibling of an only"',
			]);
			expect(
				auditSwitchPins(fixture, pinAt("tests/support.ts", "a support pin")),
			).toEqual([
				"fam.Inject: pin test tests/support.ts is not a test file vitest collects",
			]);
		});

		it("does not let an options-object skip, unread options, a body skip, an options .only's sibling or an excluded file name a pin", () => {
			// Recurrence: #4399 verify r2 F2, F3 and Q5. Each form left both
			// gates green while vitest skipped the test or never collected the
			// file (state-space rows 7 to 10, 12 and 14).
			const fixture = tree({ "Pass.cfg": PASS });
			const pinAt = (test: string, title: string) =>
				registry({ ...GOOD, Inject: { ...GOOD.Inject, test, title } });
			for (const title of [
				"a pin with a timeout option",
				"a pin with a timeout",
			])
				expect(
					auditSwitchPins(fixture, pinAt("tests/p.test.ts", title)),
				).toEqual([]);
			for (const title of [
				"an options-skipped pin",
				"an options-todo pin",
				"an options-fails pin",
				"a pin with unread options",
				"a pin in an options-skipped suite",
				"a pin that skips itself",
				"a pin that skips by its parameter",
			])
				expect(
					auditSwitchPins(fixture, pinAt("tests/p.test.ts", title)),
				).toEqual([
					`fam.Inject: tests/p.test.ts declares no test titled "${title}"`,
				]);
			expect(
				auditSwitchPins(
					fixture,
					pinAt("tests/options-only.test.ts", "a sibling of an options only"),
				),
			).toEqual([
				'fam.Inject: tests/options-only.test.ts declares no test titled "a sibling of an options only"',
			]);
			expect(
				auditSwitchPins(
					fixture,
					pinAt("tests/fixtures/f.test.ts", "a support pin"),
				),
			).toEqual([
				"fam.Inject: pin test tests/fixtures/f.test.ts is not a test file vitest collects",
			]);
		});

		it("checks every further test a pin names in also", () => {
			// Recurrence: #4399 review F2. One value encoded two behaviours
			// (SpendLicense == BridgeNoAdvance) and only one had a test.
			const fixture = tree({ "Pass.cfg": PASS });
			const also = [{ test: "tests/p.test.ts", title: "a gone pin" }];
			expect(
				auditSwitchPins(
					fixture,
					registry({ ...GOOD, Inject: { ...GOOD.Inject, also } }),
				),
			).toEqual([
				'fam.Inject: tests/p.test.ts declares no test titled "a gone pin"',
			]);
		});

		it("admits a narrowing value only with its reason", () => {
			const fixture = tree({
				"Pass.cfg": PASS,
				"Narrow.cfg": cfg("pass", '    Mode = "atomic"\n    Size = 2'),
			});
			expect(auditSwitchPins(fixture, registry(GOOD))).toEqual([
				'fam.Mode: pinned "on", but formal/fam/Narrow.cfg (expect: pass) has "atomic"',
			]);
			const narrowed = {
				...GOOD,
				Mode: {
					...GOOD.Mode,
					narrowedBy: {
						'"atomic"': { configs: ["Narrow"], reason: "a schedule on admits" },
					},
				},
			};
			expect(auditSwitchPins(fixture, registry(narrowed))).toEqual([]);
		});

		it("admits a narrowing value for the configs it names, not for every config that has it", () => {
			// Recurrence: narrowedBy was value-wide, so flipping the headline config
			// of dispatch-pipeline (SiblingRestoreQueued RestoreGatesHold FALSE to
			// TRUE) stayed green: a sibling config already had TRUE admitted (#4393).
			const fixture = tree({
				"Pass.cfg": PASS,
				"Narrow.cfg": cfg("pass", '    Mode = "atomic"\n    Size = 2'),
				"Flipped.cfg": cfg("pass", '    Mode = "atomic"\n    Size = 2'),
			});
			const narrowed = {
				...GOOD,
				Mode: {
					...GOOD.Mode,
					narrowedBy: {
						'"atomic"': { configs: ["Narrow"], reason: "a schedule on admits" },
					},
				},
			};
			expect(auditSwitchPins(fixture, registry(narrowed))).toEqual([
				'fam.Mode: pinned "on", but formal/fam/Flipped.cfg (expect: pass) has "atomic"',
			]);
			// A listed config that no longer has the value, or is unknown, is stale.
			const stale = {
				...GOOD,
				Mode: {
					...GOOD.Mode,
					narrowedBy: {
						'"atomic"': {
							configs: ["Narrow", "Flipped", "Pass"],
							reason: "a schedule on admits",
						},
					},
				},
			};
			expect(auditSwitchPins(fixture, registry(stale))).toEqual([
				'fam.Mode: stale narrowedBy "atomic"; Pass is no as-built config with that value',
			]);
		});

		it("compares a constant only against the as-built configs of modules that name it", () => {
			// Recurrence: formal/dispatch-pipeline holds two modules
			// (DispatchPipeline.tla and SiblingRestore.tla). The pass configs of one
			// assign none of the other's constants, and the gate read that absence
			// as a config with no value, so neither module's constants could be
			// pinned (#4393).
			const fixture = tree({ "Pass.cfg": PASS });
			fs.writeFileSync(
				path.join(fixture, "formal", "fam", "N.tla"),
				["---- MODULE N ----", "CONSTANTS Other", "===="].join("\n"),
			);
			fs.writeFileSync(
				path.join(fixture, "formal", "fam", "Other.cfg"),
				[
					"\\* expect: pass",
					"\\* module: N",
					"CONSTANTS",
					"    Other = 1",
					"SPECIFICATION Spec",
				].join("\n"),
			);
			const both = {
				notCodeChoice: [{ reason: "bounds", constants: ["Size", "Other"] }],
			};
			expect(auditSwitchPins(fixture, registry(GOOD, both))).toEqual([]);
			// A config of the module that does name the constant still needs a value.
			fs.writeFileSync(
				path.join(fixture, "formal", "fam", "NoMode.cfg"),
				cfg("pass", "    Size = 2"),
			);
			expect(auditSwitchPins(fixture, registry(GOOD, both))).toEqual([
				"fam.Mode: formal/fam/NoMode.cfg gives no literal value to compare",
			]);
		});
	});
});

tests/support/single-flight-scan.ts:
/**
 * Ratchet scan for hand-rolled at-most-one-in-flight state — #1753.
 *
 * `clients/single-flight.ts` owns the four guards that the ten hand-rolled
 * copies kept getting wrong (#1690, #1674, #1687, #1722). A primitive nobody
 * reaches for is a primitive that decays, so this scan makes the NEXT copy
 * argue for itself: any new module-level or class-field declaration whose name
 * contains `inFlight` fails until it is either built on the primitive or listed
 * with a reason.
 *
 * It is a ratchet, not a migration. Everything the scan finds today is listed;
 * the list is the burn-down backlog, and each entry says why it is still there.
 */

import * as fs from "node:fs";
import * as path from "node:path";
import { Lang, parse } from "@ast-grep/napi";

import type { SgNode } from "../../clients/deps/ast-grep-napi.js";
import { clientSourceFiles, clientsRelative } from "./session-state-scan.js";

/** One `inFlight`-named declaration the scan found. */
export interface InFlightDeclaration {
	/** `clients/`-relative posix path. */
	file: string;
	/** The declared identifier. */
	symbol: string;
	/** 1-based line number in the original source. */
	line: number;
	/** `file:symbol` — the key exemptions are written against. */
	key: string;
}

/** Every `inFlight` spelling in one source, classified or reported. */
export interface InFlightScan {
	declarations: InFlightDeclaration[];
	/** `unclassified spelling at <file>:<line>: <text> (<kind> under <parent>)`. */
	unclassified: string[];
}

/**
 * What the scan classifies (#4429: a population-deriving scanner fails closed).
 *
 * The needle is every identifier-like syntax node whose name contains
 * `inFlight` or `InFlight`, read from the TypeScript AST, so a comment or a
 * string that names one is not a node and never counts. Each node lands in
 * exactly one role, decided by the grammar position it fills:
 *
 * - `state`, counted: a variable declarator's binding outside every function
 *   (module state, destructured or not), a class field (any modifier set,
 *   `#private`, annotated or not, or a constructor parameter property), an
 *   interface or type member, and an
 *   object-literal key (the false-positive direction, kept from the regex scan
 *   this replaced: a person dismisses it with one exemption line).
 * - `local`: a binding inside a function (a plain parameter, a function-scoped
 *   declarator, a `catch` or `for…of` binding). State a factory closes over is
 *   the documented false negative: by shape it is any function local.
 * - `name`: the name of a function, method, class, interface, type or enum.
 * - `reference`: a read, a call, an assignment to an existing binding (the
 *   clear-in-finally), a member access, an import or export specifier, a type
 *   reference.
 *
 * A node in any other position is UNCLASSIFIED and reported with its file and
 * line, never skipped: a declaration form this table does not know must red
 * until it is classified here. The regex scan this replaced missed
 * `override`, `declare` and `accessor` fields, unannotated fields and
 * multi-declarator lines, and said nothing.
 */
const NEEDLE_KINDS = [
	"identifier",
	"property_identifier",
	"private_property_identifier",
	"shorthand_property_identifier",
	"shorthand_property_identifier_pattern",
	"type_identifier",
] as const;

type Role = "state" | "local" | "name" | "reference";

/** Parents whose child identifier is always an expression or type use. */
const REFERENCE_PARENTS = new Set([
	"arguments",
	"array",
	"arrow_function",
	"as_expression",
	"assignment_expression",
	"augmented_assignment_expression",
	"await_expression",
	"binary_expression",
	"call_expression",
	"export_specifier",
	"expression_statement",
	"generic_type",
	"import_specifier",
	"member_expression",
	"new_expression",
	"non_null_expression",
	"object",
	"parenthesized_expression",
	"return_statement",
	"satisfies_expression",
	"sequence_expression",
	"spread_element",
	"subscript_expression",
	"template_substitution",
	"ternary_expression",
	"throw_statement",
	"type_annotation",
	"type_arguments",
	"type_query",
	"unary_expression",
	"union_type",
	"update_expression",
	"yield_expression",
]);

/** Declarations whose `name` field is a callable or type name, not state. */
const NAME_PARENTS = new Set([
	"abstract_class_declaration",
	"class_declaration",
	"enum_declaration",
	"function_declaration",
	"function_expression",
	"generator_function_declaration",
	"interface_declaration",
	"method_definition",
	// A method SIGNATURE declares a callable, like `method_definition`, not a
	// field of at-a-time state: `hasNotifyInFlight?(filePath): boolean`
	// (`LSPClient`, #4532 gap 9 round 3) asks the queue a question.
	"method_signature",
	"type_alias_declaration",
]);

/** Ancestors that make a binding function-scoped. */
const FUNCTION_SCOPES = new Set([
	"arrow_function",
	"class_static_block",
	"function_declaration",
	"function_expression",
	"generator_function",
	"generator_function_declaration",
	"method_definition",
]);

/** Parameter children that make a constructor parameter a class field. */
const PARAMETER_PROPERTY_MODIFIERS = new Set([
	"accessibility_modifier",
	"override_modifier",
	"readonly",
]);

/** Destructuring wrappers a binding can sit inside. */
const PATTERN_KINDS = new Set([
	"array_pattern",
	"assignment_pattern",
	"object_assignment_pattern",
	"object_pattern",
	"pair_pattern",
	"rest_pattern",
]);

function sameNode(a: SgNode | null | undefined, b: SgNode): boolean {
	if (!a) return false;
	const ra = a.range();
	const rb = b.range();
	return ra.start.index === rb.start.index && ra.end.index === rb.end.index;
}

function insideFunction(node: SgNode): boolean {
	for (let up = node.parent(); up; up = up.parent()) {
		if (FUNCTION_SCOPES.has(String(up.kind()))) return true;
	}
	return false;
}

/** The role of a binding nested in a destructuring pattern, or undefined. */
function patternBindingRole(node: SgNode): Role | undefined {
	let child = node;
	let up = node.parent();
	while (up && PATTERN_KINDS.has(String(up.kind()))) {
		child = up;
		up = up.parent();
	}
	if (!up) return undefined;
	const kind = String(up.kind());
	if (kind === "variable_declarator" && sameNode(up.field("name"), child)) {
		return insideFunction(up) ? "local" : "state";
	}
	if (
		(kind === "required_parameter" || kind === "optional_parameter") &&
		sameNode(up.field("pattern"), child)
	) {
		return "local";
	}
	return undefined;
}

function roleOf(node: SgNode): Role | undefined {
	const parent = node.parent();
	if (!parent) return undefined;
	const kind = String(parent.kind());
	const fills = (field: string) => sameNode(parent.field(field), node);
	if (node.kind() === "shorthand_property_identifier_pattern") {
		return patternBindingRole(node);
	}
	if (PATTERN_KINDS.has(kind)) return patternBindingRole(node);
	switch (kind) {
		case "variable_declarator":
			if (!fills("name")) return "reference";
			return insideFunction(parent) ? "local" : "state";
		case "public_field_definition":
		case "property_signature":
			return fills("name") ? "state" : "reference";
		case "pair":
			return fills("key") ? "state" : "reference";
		case "required_parameter":
		case "optional_parameter":
			if (!fills("pattern")) return "reference";
			// A constructor parameter with an accessibility, `readonly` or
			// `override` modifier is a parameter property: a class field.
			return parent
				.children()
				.some((child) => PARAMETER_PROPERTY_MODIFIERS.has(String(child.kind())))
				? "state"
				: "local";
		case "catch_clause":
			// The grammar puts only the binding directly under the clause.
			return "local";
		case "for_in_statement":
			// `for (const x of y)` binds `x`; `for (x of y)` assigns an existing one.
			if (!fills("left")) return "reference";
			return parent.field("kind") ? "local" : "reference";
	}
	if (NAME_PARENTS.has(kind)) return fills("name") ? "name" : undefined;
	if (REFERENCE_PARENTS.has(kind)) return "reference";
	return undefined;
}

const NEEDLE_TEXT = /[iI]nFlight/;

/** Classify every `inFlight` spelling in one source text. */
export function classifyInFlightSpellings(
	file: string,
	source: string,
): InFlightScan {
	const scan: InFlightScan = { declarations: [], unclassified: [] };
	if (!NEEDLE_TEXT.test(source)) return scan;
	const lines = source.split("\n");
	const root = parse(Lang.TypeScript, source).root();
	const nodes = root.findAll({
		rule: {
			any: NEEDLE_KINDS.map((kind) => ({ kind, regex: NEEDLE_TEXT.source })),
		},
	});
	for (const node of nodes) {
		const line = node.range().start.line + 1;
		const role = roleOf(node);
		if (role === undefined) {
			scan.unclassified.push(
				`unclassified spelling at ${file}:${line}: ${lines[line - 1]?.trim() ?? ""} (${node.kind()} under ${node.parent()?.kind()})`,
			);
			continue;
		}
		if (role !== "state") continue;
		const symbol = node.text().replace(/^#/, "");
		scan.declarations.push({ file, symbol, line, key: `${file}:${symbol}` });
	}
	scan.declarations.sort((a, b) => a.line - b.line);
	return scan;
}

/** Find every `inFlight`-named module-state declaration in one source text. */
export function findInFlightDeclarations(
	file: string,
	source: string,
): InFlightDeclaration[] {
	return classifyInFlightSpellings(file, source).declarations;
}

/** The module that owns the primitive, which is exempt by definition. */
const PRIMITIVE_MODULE = "single-flight.ts";

/** Classify every `inFlight` spelling in every `clients/` source. */
export function scanInFlightSpellings(): InFlightScan {
	const total: InFlightScan = { declarations: [], unclassified: [] };
	for (const absolute of clientSourceFiles()) {
		const file = clientsRelative(absolute);
		if (path.posix.basename(file) === PRIMITIVE_MODULE) continue;
		const scan = classifyInFlightSpellings(
			file,
			fs.readFileSync(absolute, "utf8"),
		);
		total.declarations.push(...scan.declarations);
		total.unclassified.push(...scan.unclassified);
	}
	return total;
}

/** Scan every `clients/` source for hand-rolled in-flight declarations. */
export function scanInFlightDeclarations(): InFlightDeclaration[] {
	return scanInFlightSpellings().declarations;
}

